  str_guide_pop_title = "คอมโบต่อเนื่อง",
  str_guide_pop_desc = "เมื่อเดินต่อเนื่องจนถึง<color=#ff8f3d>ความยาวระยะหนึ่ง</color> จะ<color=#ff8f3d>เกิดคอมโบต่อเนื่องโดยอัตโนมัติ</color> \nโดยทั่วไป <color=#ff8f3d>ยิ่งเชื่อมโยงได้ยาวเท่าไร</color> คอมโบต่อเนื่อง<color=#ff8f3d>ก็ยิ่งรุนแรงมากขึ้นเท่านั้น</color>\nคอมโบต่อเนื่องแต่ละอย่างของออโรเรียนมีเอฟเฟกต์และเงื่อนไขการเกิดที่แตกต่างกัน ดังนั้นผสมและจับคู่กันตามที่คุณเห็นสมควรได้เลย!",
