  str_guide_pop_extra_lineskill = "คุณค่าของออโรเรียนที่แท้จริงมาจากสิ่งที่แสดงออกมานอกเหนือจากพลังของเธอ\n — สารของไรน์ฮาร์ต III —",
  str_guide_pop_title_moreline = "การเชื่อมโยงออโรเรียนหลายราย",
  str_guide_pop_desc_moreline = "เมื่อจัดวางออโรเรียนหลายราย ออโรเรียนที่มีธาตุตรงกับช่องที่ต่อเนื่องเท่านั้นจึงจะเดินได้\n<color=#ff5f51>ช่องสีแดง</color>จะกระตุ้นออโรเรียนธาตุ<color=#ff5f51>ไฟ</color>, <color=#6fd5ff>ช่องสีน้ำเงิน</color>จะกระตุ้นออโรเรียนธาตุ<color=#6fd5ff>น้ำ</color>, \n<color=#85ff3b>ช่องสีเขียว</color>จะกระตุ้นออโรเรียนธาตุ<color=#85ff3b>ไม้</color> และ <color=#fee039>ช่องสีเหลือง</color>จะกระตุ้นออโรเรียนธาตุ<color=#fee039>สายฟ้า</color>\nไม่ต้องกังวล กัปตันออโรเรียนจะ<color=#ff8f3d>เพิกเฉยต่อธาตุของช่อง</color> แล้วเดินได้ทุกรอบ",
  str_guide_pop_extra_moreline = "โลกใบนี้ได้รับพรจากเทพธิดาผู้ซึ่งเติมเต็มหัวใจผู้คนด้วยแสงสว่าง\n —สารของไรน์ฮาร์ต I—",
  str_guide_pop_title_mainskill1 = "สกิลใช้งาน",
  str_guide_pop_desc_mainskill1 = "สกิลใช้งานแบ่งเป็นสกิลจู่โจมเปิดฉากและสกิลโจมตีปกติ <color=#ff8f3d>สกิลจู่โจมเปิดฉาก</color>สามารถใช้ได้ทันทีเมื่อเริ่มการต่อสู้!\nสกิลใช้งานต้อง<color=#ff8f3d>ใช้ก่อนการเชื่อมโยง</color> และ<color=#ff8f3d>จะเข้าช่วงคูลดาวน์</color>หลังใช้งาน\nออโรเรียนแต่ละรายจะมีสกิลใช้งานแตกต่างกัน การผสมสกิลที่ต่างกันอย่างเหมาะสมจะทำคุณประโยชน์ได้มหาศาล!",
  str_guide_pop_extra_mainskill1 = "เวลาที่ยาวนานได้เพาะเมล็ดพันธุ์แห่งความแตกแยกไว้ในจิตใจเรา ทว่าก็ได้หล่อเลี้ยงสิ่งมหัศจรรย์อันงดงามมากมายเช่นกัน\n —สารของไรน์ฮาร์ต II—",
  str_guide_pop_title_mainskill2 = "สกิลเปลี่ยนสีช่อง",
  str_guide_pop_desc_mainskill2 = "สกิลเปลี่ยนสีช่องสามารถ<color=#ff8f3d>เปลี่ยนสีช่องบางส่วน</color>และเปลี่ยน <color=#ff8f3d>กระดาน Alchemy</color> ได้\nการเปลี่ยนสีช่องจะทำให้<color=#ff8f3d>มีโอกาสเชื่อมโยง</color>มากขึ้น และเป็นสกิลสนับสนุนที่แข็งแกร่งที่สุด\nเปลี่ยนสีช่องในช่วงเวลาที่เหมาะสมเพื่อทำตามกลยุทธ์ของคุณในการพลิกเกม!",
  str_guide_pop_extra_mainskill2 = "สิ่งเดียวที่ไม่เคยเปลี่ยนแปลงก็คือการเปลี่ยนแปลงนั่นเอง\n —สารของไรน์ฮาร์ต IV—",
  str_guide_pop_title_levelup = "อัปเกรด",
  str_guide_pop_desc_levelup = "เพิ่มเลเวลและรวบรวมพลังออโรเรียน",
  str_guide_pop_extra_levelup = "คำอธิบายเลเวล XXX",
  str_guide_pop_title_lineskillrange = "ระยะคอมโบต่อเนื่อง",
  str_guide_pop_desc_lineskillrange = "การยืนยันระยะของคอมโบต่อเนื่องเป็นวิธีพื้นฐานที่สุดในการเพิ่มประสิทธิภาพการต่อสู้\nสกิลที่ต่างกันของออโรเรียนนั้นมีระยะที่ต่างกัน หลังจากเชื่อมโยงแล้ว<color=#ff8f3d>อย่ายกนิ้วออก</color> คุณจะได้เห็น<color=#ff8f3d>ตัวอย่าง</color>ระยะของทุกสกิล\n<color=#ff8f3d>การปรับจุดสิ้นสุดของการเชื่อมโยง</color>จะเปลี่ยนพื้นที่ที่สกิลของออโรเรียนส่งผล เรื่องนี้สำคัญมากนะ!",
  str_guide_pop_extra_lineskillrange = "เกียรติสูงสุดในหมู่สหาย คือการเชื่อใจกันและกันด้วยชีวิต\n —สารของไรน์ฮาร์ต VII—",
  str_guide_pop_title_leaderskill = "สกิลกัปตัน",
  str_guide_pop_desc_leaderskill = "ออโรเรียนบางรายมีสกิลติดตัวพิเศษที่เหนือกว่าออโรเรียนอื่น ๆ นั่นคือสกิลกัปตัน!",
  str_guide_pop_extra_leaderskill = "สกิลกัปตันหายากมากและสามารถเพิ่มค่าความสามารถของออโรเรียนที่มีธาตุเดียวกันได้",
  str_guide_pop_title_jiguan = "กับดัก",
  str_guide_pop_desc_jiguan = "กับดักไฟจะ<color=#ff8f3d>หมุนอย่างสม่ำเสมอ</color> ทำดาเมจกับเป้าหมายใน<color=#ff8f3d>แนวนอนหรือแนวตั้ง</color> \nกับดักอาจจะ<color=#ff8f3d>โจมตีเรา</color>หรือ<color=#ff8f3d>ศัตรูของเรา</color>ก็ได้ มันจะทำงานอย่างมหัศจรรย์ถ้าใช้อย่างมีประสิทธิภาพ\nพยายามอยู่ให้ห่างระยะโจมตีของมันและระวังอย่าให้กับดักขวางการเชื่อมโยงของคุณ!",
  str_guide_pop_extra_jiguan = "สมัยก่อนมีขยะมากมายก่ายกอง แต่ก็มี...ของสนุก ๆ เยอะเหมือนกัน! ว่าไหม?\n —บันทึกการสังเกตของกรอนรู—",
  str_guide_pop_title_muchaoguai = "มอนสเตอร์สร้างสมุน",
  str_guide_pop_desc_muchaoguai = "มอนสเตอร์สร้างสมุน<color=#ff8f3d>ไม่สามารถเคลื่อนที่</color> แต่จะ<color=#ff8f3d>เรียกอิคลิพไซท์มาอย่างต่อเนื่อง</color> \nถ้าคุณไม่สามารถเอาชนะพวกมันภายในเวลาที่กำหนด สนามรบจะเต็มไปด้วยศัตรู\n<color=#ff8f3d>โจมตีมอนสเตอร์โดยตรง</color>เป็นวิธีจัดการที่ดีที่สุด โดยเฉพาะกับมอนสเตอร์ขนาดกลาง\nและอย่าบอกว่าฉันไม่เตือนนะ: <color=#ff8f3d>จัดการพวกมันด้วยการโจมตีวงกว้างสิ</color>!",
  str_guide_pop_extra_muchaoguai = "อิคลิพไซท์บางตัวน่าขยะแขยงสุด ๆ เวลาตัวขาดจะมีเมือกเหนียว ๆ ของ... (ข้อมูลถูกลบ)\n —บันทึกการสังเกตของกรอนรู—",
  str_guide_pop_title_shenyuan = "ช่องเหวลึก",
  str_guide_pop_desc_shenyuan = "ช่องเหวลึกไม่สามารถเดินผ่านได้ แต่มอนสเตอร์บินสามารถผ่านไปได้ คุณใช้การเทเลพอร์ตได้",
  str_guide_pop_extra_shenyuan = "ผ่านด้วยการเทเลพอร์ตได้",
  str_guide_pop_title_moredamge = "ประเภทร่างกายและดาเมจของอิคลิพไซท์",
  str_guide_pop_desc_moredamge = "อิคลิพไซท์มี<color=#ff8f3d>ขนาด</color>หลากหลาย ที่พบเจอบ่อยที่สุดคืออิคลิพไซท์หนึ่งช่อง\nยังมีอิคลิพไซท์ยืนสี่ช่องและพวกที่ตัวใหญ่กว่านั้นอีกด้วย ถึงแม้จะตัวใหญ่และแข็งแกร่งแต่ก็ได้รับดาเมจมากกว่าในการต่อสู้\n<color=#ff8f3d>เพราะยึดครองหลายช่อง จึงรับดาเมจหลายเท่าจากการโจมตีเป็นวงกว้าง </color>เช่นเดียวกับการโจมตีต่อเนื่อง!",
  str_guide_pop_extra_moredamge = "ยิ่งศัตรูตัวใหญ่ ก็ยิ่งจัดการได้ง่าย แค่หลับตาแล้วตีพวกมันซะ\n —คำคมจากบาร์ตัน (ไม่ได้เผยแพร่)—",
  str_guide_pop_title_leveltask = "เควสต์ด่าน",
  str_guide_pop_desc_leveltask = "เควสต์ด่านมีหลากหลายแบบ เคลียร์ด่านได้โดยการทำเควสต์ให้สำเร็จ",
  str_guide_pop_extra_leveltask = "เคลียร์ด่านโดยการทำเควสต์ในด่านให้สำเร็จ",
  str_guide_pop_title_escape = "จุดหลบหนี",
  str_guide_pop_desc_escape = "จุดหลบหนีเป็นฟีเจอร์ที่ใช้เคลียร์ด่านพิเศษได้ โดย<color=#ff8f3d>เดินไปให้ถึงช่องนั้น</color> คุณก็จะชนะทันที\nโปรดทราบว่าจุดหลบหนีจะ<color=#ff8f3d>ล็อกอยู่</color>ในตอนแรก และจะปลดล็อกได้โดยบรรลุเงื่อนไขบางประการเท่านั้น\nมีเงื่อนไขปลดล็อกมากมาย เช่น <color=#ff8f3d>เก็บรวบรวมไอเทมหรือเอาชนะอิคลิพไซท์</color>",
  str_guide_pop_extra_escape = "การหนีไม่ใช่เรื่องน่าอาย ถอยทัพชั่วคราวก็เพื่อความทะเยอทะยานที่มากขึ้น\n —จดหมายจากชาโรนา—",
  str_guide_pop_title_monsterinfo = "ดูรายละเอียด",
  str_guide_pop_desc_monsterinfo = "<color=#ff8f3d>แตะค้างที่ช่องใต้เท้าของมอนสเตอร์</color>เพื่อดูระยะโจมตีและข้อมูลอื่น ๆ ของมัน\nการจับตาดูคุณลักษณะของศัตรูจะทำให้คุณไร้พ่าย!",
  str_guide_pop_extra_monsterinfo = "รู้เขารู้เรา รบร้อยครั้งก็ไม่มีวันพ่ายแพ้\nข้อความส่วนหนึ่งจากตำราเก่าไม่ทราบที่มา—",
  str_guide_pop_title_jiguangshike = "ออโรราไทม์",
  str_guide_pop_desc_jiguangshike = "เมื่อการเชื่อมโยง<color=#ff8f3d>ถึง 15 ช่อง</color> จะเกิดออโรราไทม์ และคุณจะได้รับโอกาสเดินเพิ่มอีกครั้ง\nในช่วงเวลาออโรราไทม์ ออโรเรียนจะใช้สกิลใช้งานที่เตรียมไว้ได้และยังสามารถเกิดคอมโบต่อเนื่องด้วยการเชื่อมโยงครั้งใหม่อีกด้วย\nออโรราไทม์<color=#ff8f3d>จะเกิดขึ้นเพียงรอบละหนึ่งครั้งเท่านั้น</color> ทำให้คุณได้รับประโยชน์อย่างมากในการต่อสู้",
  str_guide_pop_extra_jiguangshike = "เรารู้เพียงเศษเสี้ยวเกี่ยวกับพลังเวทแห่งแสงสว่าง\n —ข้อความส่วนหนึ่งจากตำราเก่าไม่ทราบที่มา—",
  str_guide_pop_title_jianglihuihe = "เวลาโบนัส",
  str_guide_pop_desc_jianglihuihe = "เมื่อเคลียร์ดันเจี้ยน \"แหล่งกบดานทมิฬ รัตติกาลสีขาว\" ที่ระดับความยากใด ๆ ตามจำนวนครั้งที่กำหนด จะเข้าสู่ช่วงเวลาโบนัส\nอิคลิพไซท์เน่าเปื่อยหลายตัวจะปรากฏบนสนามรบ กำจัดพวกมันจะได้รับไนท์เทียมพิเศษ!\nระวังให้ดี พวกมันมี<color=#ff8f3d>ค่า ACT สูงมาก</color> นั่นทำให้มันเคลื่อนที่ได้ไกลและหลบการโจมตีของเราได้",
  str_guide_pop_extra_jianglihuihe = "ช่วงเวลาที่โชคดีเกิดขึ้นได้วันละครั้ง!\n —แหล่งกบดานทมิฬ รัตติกาลสีขาว: แนะนำ—",
  str_guide_warn_10111 = "ตรงนี้มีทางเดิน! ลองโจมตีตอนเดินผ่านอิคลิพไซท์\nพวกนั้นสิ",
  str_guide_warn_10121 = "ใช่ ทางนี้ด้วย! คุณจะโจมตีศัตรูหลายตัวพร้อมกัน\nในครั้งเดียวก็ได้!",
  str_guide_warn_10131 = "ใช้คอมโบต่อเนื่องเพื่อเอาชนะอิคลิพไซท์ทั้งหมดในครั้งเดียว!",
  str_guide_warn_10211 = "การเดินไปในช่องไม้จะกระตุ้นให้โคลเวอร์ทำงาน!",
  str_guide_warn_10311 = "ระวัง หลังจากใช้สกิลใช้งานแล้ว จะเข้าสู่เวลาคูลดาวน์!",
  str_guide_warn_10511 = "โซย่าเป็นผู้รักษา ลองใช้ช่องสีน้ำเงินเมื่อบาดเจ็บสิ!",
  str_guide_warn_10521 = "คอมโบต่อเนื่องของโซย่าสามารถฟื้นฟู HP ได้!",
  str_guide_warn_10531 = "การผสมสกิลใช้งานอย่างเหมาะสมจะสร้างเอฟเฟกต์ได้มหาศาล!",
  str_guide_warn_10611 = "ท่าทางเราควรปรึกษาบางอย่างกันต่อหน้านะ...",
