  str_guide_warn_50019 = "หลักจากเริ่มอีเวนต์คลื่นความร้อน คุณจะปลดล็อกเรื่องราวและด่านการท้าทายเพิ่มเติมได้!",
  str_guide_warn_50020 = "หลังจากเริ่มอีเวนต์จี๊ดขึ้นสมอง คุณจะช่วยฉันเรื่องแผนการฤดูร้อนอันชาญฉลาดได้",
  str_guide_warn_50021 = "คุณจะได้รับรางวัลลงชื่อในช่วงอีเวนต์ ดังนั้นอย่าลืมเข้าสู่ระบบทุกวันนะ!",
  str_guide_warn_50022 = "นี่คือร้านบัตรของขวัญพรินนี่ ที่คุณสามารถนำบัตรของขวัญพรินนี่มาแลกเป็นรางวัลสุดว้าวได้!",
  str_guide_warn_50023 = "การเข้าร่วมอีเวนต์จะทำให้คุณทำเควสต์ในหนังสืออีเวนต์พิเศษให้สำเร็จได้ และได้รับรางวัลมากมาย",
  str_guide_warn_50024 = "หากมีข้อสงสัยใด ๆ สามารถดูรายละเอียดกติกาอีเวนต์ได้ที่นี่!",
  str_guide_warn_50025 = "เพิ่มเลเวลหนังสืออีเวนต์พิเศษได้โดยการทำเควสต์ในหนังสือให้สำเร็จและรับคะแนนการมีส่วนร่วม",
  str_guide_warn_50026 = "ทุกครั้งที่อัปเกรดหนังสืออีเวนต์พิเศษ จะได้รับรางวัลตามเลเวล!",
  str_guide_warn_50027 = "ดูรางวัลหนังสืออีเวนต์พิเศษทั้งหมดของคุณได้ที่นี่!",
  str_guide_warn_50028 = "แตะที่นี่เพื่อดูเควสต์หนังสืออีเวนต์พิเศษ",
  str_guide_warn_50029 = "เควสต์หนังสืออีเวนต์พิเศษมีทั้งเควสต์ถาวรและเควสต์อีเวนต์",
  str_guide_warn_50030 = "เควสต์อีเวนต์จะเปิดให้ทำได้ในบางช่วงเวลาเท่านั้น โปรดทำเควสต์ให้สำเร็จภายในเวลาที่กำหนด!",
  str_guide_warn_50031 = "ลูกค้าเริ่มต่อแถวกันแล้ว... เราควรเริ่มทำน้ำแข็งไสเพิ่มให้เร็วที่สุด!",
  str_guide_warn_50032 = "ลูกค้าแต่ละคนจะสั่งน้ำแข็งไสต่างกันไป ต้องเลือกส่วนผสมที่จะใช้ให้ถูกต้อง!",
  str_guide_warn_50033 = "อารมณ์ของลูกค้าจะเริ่มแย่ลงในขณะที่รอ ยิ่งอารมณ์ดีมากเท่าไร เรตติ้งของคุณยิ่งดีขึ้นเท่านั้น!",
  str_guide_warn_50034 = "ในการทำน้ำแข็งไส ก่อนอื่นต้องเลือกขนาดให้ถูกต้อง",
  str_guide_warn_50035 = "จากนั้นก็เลือกน้ำเชื่อมได้เลย",
  str_guide_warn_50036 = "เลือกส่วนผสมให้ถูกต้อง! ลำดับในการเลือกส่วนผสมและน้ำเชื่อมไม่มีผลใด ๆ ตรงนี้!",
  str_guide_warn_50037 = "แตะที่ลูกค้าเพื่อส่งน้ำแข็งไสให้ แล้วออเดอร์ก็จะเสร็จสมบูรณ์!",
  str_guide_warn_50038 = "การทำออเดอร์เสร็จติดต่อกันตามจำนวนที่กำหนดจะทำให้เกิดจี๊ดขึ้นสมอง ช่วยให้คุณทำออเดอร์ที่ตามมาได้ในไม่กี่วินาที!",
  str_guide_warn_50039 = "นอกจากนี้คุณจะได้รับรางวัลโบนัสหลังจากทำออเดอร์ติดต่อกันอีกด้วย!",
  str_guide_warn_50040 = "ไม่ต้องห่วงถ้าทำน้ำแข็งไสพลาด แค่แตะที่นี่เพื่อโยนทิ้งไป!",
  str_guide_warn_50041 = "แตะที่นี่เพื่อหยุดผลิตน้ำแข็งไสชั่วคราวแล้วพักสักหน่อย",
  str_guide_warn_50042 = "เรื่องที่ต้องรู้เกี่ยวกับการทำน้ำแข็งไสก็มีเท่านี้แหละ! กลับไปลุยงานต่อเถอะ!",
  str_guide_warn_50043 = "ตอนนี้อีเวนต์เอนด์เกมเริ่มแล้ว! เข้าตรงนี้แล้วเตรียมพร้อมรับความท้าทายสุดตื่นเต้น!",
  str_guide_warn_50044 = "ท้าทายให้เสร็จสิ้นเพื่อรับคะแนนแล้วนำมาแลกรางวัลสุดว้าวได้ที่นี่!",
  str_guide_warn_50045 = "ดูเรื่องราวการผจญภัยของอีเวนต์นี้ได้ในตำนานเอนด์เกม",
  str_guide_warn_50046 = "ถ้าคุณต้องการไล่ตามเนื้อเรื่องที่ผ่านมา สามารถย้อนดูได้ที่นี่",
  str_guide_warn_50047 = "รับความท้าทายต่าง ๆ จากอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษของคุณให้เสร็จสิ้น!",
  str_guide_warn_50048 = "ลงชื่อทุกวันเพื่อรับรางวัลสุดพิเศษ! อย่าลืมเข้าเกมทุกวันนะ!",
  str_guide_warn_50049 = "ด่านนี้ประกอบด้วยกลไกพิเศษ คุณจะต้องเลือกระดับความยากที่เหมาะสมก่อนที่จะรับความท้าทาย!",
  str_guide_warn_50050 = "ก่อนอื่นให้เลือกระดับความยากของด่าน ความยากแต่ละระดับจะมีคะแนนพื้นฐานที่สัมพันธ์กัน",
  str_guide_warn_50051 = "จากนั้นเลือกเอฟเฟกต์เพิ่มเติมของด่าน เอฟเฟกต์แต่ละอย่างจะให้ตัวคูณคะแนนที่สัมพันธ์กัน",
  str_guide_warn_50052 = "นำคะแนนพื้นฐานไปคูณกับตัวคูณรวมจะได้เป็นคะแนนสุดท้าย!",
  str_guide_warn_50053 = "หลังจากเลือกความยากแล้ว ก็เริ่มต่อสู้ได้เลย!",
  str_guide_warn_50054 = "ระเบิดความมันส์กับศึกปะทะดูนไฟร์! การผจญภัยครั้งใหม่เริ่มแล้ว!",
  str_guide_warn_50055 = "ท้าทายโหมดกองหน้าทำลายล้างทุกวัน รับคุณความดีโดยการโค่นล้มศัตรูที่หลั่งไหลกันมาไม่หยุด",
  str_guide_warn_50056 = "ยิ่งได้รับคุณความดีมากเท่าไร อันดับดูนไฟร์ก็ยิ่งสูงขึ้น และจะได้รับรางวัลคุณความดีมากขึ้นอีกด้วย",
  str_guide_warn_50057 = "เข้าร่วมอีเวนต์ศึกปะทะดูนไฟร์เพื่อทำเควสต์ในหนังสืออีเวนต์พิเศษให้สำเร็จ",
  str_guide_warn_50058 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50059 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_50060 = "อีเวนต์จดหมายจากสายลมเริ่มแล้ว! คุณพร้อมสำหรับการผจญภัยครั้งใหม่หรือยัง?",
  str_guide_warn_50061 = "รับขนมสหภาพจากด่านเนื้อเรื่องหลักและด่านชิงทรัพยากรที่ต้องใช้ปริซึม",
  str_guide_warn_50062 = "ขนมสหภาพสามารถใช้ฟื้นฟูสำนักไปรษณีย์สาขาอีราเวลได้! ไปที่สำนักไปรษณีย์กันเถอะ!",
  str_guide_warn_50063 = "เข้าเล่นด่านเนื้อเรื่องอีเวนต์และซ่อมแซมสำนักไปรษณีย์ คุณจะสำเร็จเควสต์ที่เกี่ยวข้องในหนังสืออีเวนต์พิเศษ",
  str_guide_warn_50064 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50065 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_50066 = "เรามาถึงสำนักไปรษณีย์สาขาอีราเวลที่ปิดร้างแล้ว! ใช้ขนมสหภาพเพื่อเริ่มซ่อมแซมเลย!",
  str_guide_warn_50067 = "คุณสามารถจัดทีมหลายทีมเพื่อท้าทายบอส โดยผลรวมดาเมจที่ทุกทีมทำได้จะบันทึกเป็นดาเมจสุดท้ายที่คุณทำได้",
  str_guide_warn_50068 = "หากไม่ได้เข้าร่วมในศึกครั้งนี้ คุณจะไม่ได้รับแรงค์หรือตราสัญลักษณ์",
  str_guide_warn_50069 = "แตะที่นี่เพื่อดูรายละเอียดเกี่ยวกับแรงค์",
  str_guide_warn_50070 = "อีเวนต์เงามืดแห่งราตรีกาลเริ่มแล้ว! ดำดิ่งสู่การผจญภัยครั้งใหม่ในอัมบราตัน!",
  str_guide_warn_50071 = "มีส่วนร่วมในอารีน่าใต้ดินของอัมบราตันและท้าทายนักสู้มืออาชีพทุกรูปแบบเพื่อรับเกียรติยศ!",
  str_guide_warn_50072 = "รับเกียรติยศในอารีน่าใต้ดินเพื่อปลดล็อกรางวัลพิเศษมากมาย พร้อมกับเผยความลับแห่งถนนครอสสตรีท",
  str_guide_warn_50073 = "เข้าต่อสู้ในการท้าทายของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษให้เสร็จสิ้น!",
  str_guide_warn_50074 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50075 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_50076 = "อีเวนต์เนื้อเรื่องหลักมาแล้ว! พบกับการผจญภัยครั้งใหม่ในลูโมโพลิส!",
  str_guide_warn_50077 = "การต่อสู้จำลองจำนวนหนึ่งจะปลดล็อกเมื่อเวลาผ่านไปในคลังข้อมูลคำสั่ง... ไปลุยเพื่อรับกิตติศัพท์กัน!",
  str_guide_warn_50078 = "สะสมกิตติศัพท์เพื่อปลดล็อกรางวัลสุดพิเศษ!",
  str_guide_warn_50079 = "เข้าต่อสู้ในการท้าทายของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษให้เสร็จสิ้น!",
  str_guide_warn_50080 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50081 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_50082 = "ดิสก์ข้อมูลแต่ละแผ่นมีสถานการณ์การต่อสู้ที่แตกต่างกัน เสร็จสิ้นการต่อสู้จำลองและจะใช้ดิสก์ข้อมูลที่เกี่ยวข้อง",
  str_guide_warn_50083 = "คะแนนคำสั่งใช้สำหรับเพิ่มระดับคำสั่งและปลดล็อกรางวัลที่สอดคล้องกัน",
  str_guide_warn_50084 = "ชิ้นส่วนข้อมูลมีไว้ปลดล็อกเนื้อหาในฐานข้อมูล อย่างเช่นหนังสือและรูปประจำตัว",
  str_guide_warn_50085 = "การสร้างดิสก์ข้อมูลต้องใช้เวลา แต่คุณสามารถเร่งความเร็วได้โดยใช้การเร่ง",
  str_guide_warn_50086 = "ระดับความยากมีด้วยกัน 3 ระดับสำหรับสถานการณ์การต่อสู้จำลองแต่ละสถานการณ์",
  str_guide_warn_50087 = "จำนวนรางวัลที่ได้รับจะแตกต่างกันไป ขึ้นอยู่กับระดับความยากของด่านที่เคลียร์ได้",
  str_guide_warn_50088 = "แตะที่แท็บเพื่อเปลี่ยนระดับความยาก",
  str_guide_warn_50089 = "อีเวนต์นาฬิกาทรายเริ่มแล้ว! ดำดิ่งสู่การผจญภัยครั้งใหม่ในนอร์ธแลนด์!",
  str_guide_warn_50090 = "ในบททดสอบแห่งออโรรา เราจะได้พบกับความท้าทายสุดหินมากมาย!",
  str_guide_warn_50091 = "หากคุณมั่นใจในความรู้เรื่องแอสตรามากพอ งั้นก็ไปตอบคำถามทุกประเภทในด่านรหัสคำทะเลสาบกระจกเงากันเลย!",
  str_guide_warn_50092 = "รับมิสเซิลโทได้โดยผ่านด่านเส้นทางนอร์ธแลนด์หรือใช้ปริซึมในโหมดอื่น!",
  str_guide_warn_50093 = "มิสเซิลโทสามารถนำมาแลกรางวัลหลากหลายได้ในตลาดต้นสน!",
  str_guide_warn_50094 = "เข้าต่อสู้ในการท้าทายของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษให้เสร็จสิ้น!",
  str_guide_warn_50095 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50096 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_50097 = "ที่นี่คือห้องซิมูเลชั่น สามารถจำลองสถานการณ์การต่อสู้ได้ทุกรูปแบบ",
  str_guide_warn_50098 = "วันหยุดของเมดมังกรมาแล้วนะ!",
  str_guide_warn_50099 = "ใช้ปริซึมในด่านเนื้อเรื่องหลักและด่านชิงทรัพยากรเพื่อรับจานอาหาร",
  str_guide_warn_50100 = "ใช้จานอาหารเพื่อจับรางวัลต่าง ๆ ในโทรุคิทเช่น",
  str_guide_warn_50101 = "นี่คือด่านทดลองใช้ออโรเรียนใหม่ เล่นให้ผ่านด่านจะได้รับรางวัลนะ",
  str_guide_warn_50102 = "เข้าต่อสู้ในการท้าทายของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษให้เสร็จสิ้น!",
  str_guide_warn_50103 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_50110 = "ผจญภัยครั้งใหม่ไปกับ \"ออกสำรวจใต้พิภพ\"",
