  str_guide_warn_509005 = "ที่นี่มีไอเทมมากมาย รวมทั้งเมล็ดพันธุ์ต้นไม้ด้วย ชับบ์!",
  str_guide_warn_509006 = "วางแผนการใช้จ่ายให้รอบคอบนะ! แตะที่นี่เพื่อย้อนกลับ",
  str_guide_warn_510002 = "การเลี้ยงชับบ์มี 3 แบบ คือเลี้ยงแบบกลายพันธุ์, เลี้ยงแบบมุ่งเป้า และเลี้ยงแบบเปลี่ยนสภาพ มาลองแบบกลายพันธุ์กันก่อนดีกว่า!",
  str_guide_warn_510003 = "ใส่เมล็ดพันธุ์ต้นไม้มหัศจรรย์เพื่อเป็นเมล็ดพันธุ์ตั้งต้น ชับบ์",
  str_guide_warn_510004 = "ใส่เมล็ดพันธุ์อื่นที่มีคุณภาพเดียวกัน เพื่อเป็นปัจจัยการกลายพันธุ์ ชับบ์",
  str_guide_warn_510005 = "แตะเพื่อเริ่มเพาะพันธุ์ จากนั้นรอเวลาให้ต้นไม้มหัศจรรย์เติบโตขึ้น ชับบ์!",
  str_guide_warn_510006 = "หากคุณไม่มีเวลาที่จะรอ ใช้สารละลายเพื่อเร่งความเร็ว ชับบ์",
  str_guide_warn_510007 = "ถ้ามีปัญหาอะไร แตะตรงนี้เพื่อขอความช่วยเหลือนะ ชับบ์",
  str_guide_warn_511001 = "ผืนดินสมบูรณ์อยู่ในเมนู \"ของตกแต่งพิเศษ\" แตะตรงนี้ ชับบ์!",
  str_guide_warn_511002 = "จากนั้นก็แต่ที่เมนู \"ผืนดินสมบูรณ์\" ชับบ์!",
  str_guide_warn_511003 = "นี่คือผืนดินสมบูรณ์ ชับบ์! ใช้ผืนดินนี้เพาะพันธุ์ต้นไม้มหัศจรรย์นะ ชับบ์!",
  str_guide_warn_512001 = "แตะที่นี่เพื่อตกแต่ง",
  str_guide_warn_512002 = "ผืนดินสมบูรณ์อยู่ในเมนู \"ของตกแต่งพิเศษ\" แตะตรงนี้!",
  str_guide_warn_512003 = "จากนั้นก็แต่ที่เมนู \"ผืนดินสมบูรณ์\"!",
  str_guide_warn_512004 = "นี่คือผืนดินสมบูรณ์ แตะที่นี่เพื่อวาง!",
  str_guide_warn_5110001 = "ผู้นำทางครับ, ออโรเรียนได้ถึงเลเวลสูงสุดแล้ว หากต้องการเพิ่มเลเวลต่อไป คุณต้องผ่านกระบวนการเลื่อนขั้นเพื่อทะลุขีดจำกัดปัจจุบัน",
  str_guide_warn_5110004 = "แตะเพื่อดูวัตถุดิบที่ต้องใช้สำหรับเลื่อนขั้น!",
  str_guide_warn_5110005 = "ในกรณีที่วัตถุดิบไม่เพียงพอ มีหลายวิธีในการรวบรวม รวมถึงการเก็บวัตถุดิบจากเวทีที่เกี่ยวข้องหรือเพิ่มระดับโรงงานเพื่อผลิตวัตถุดิบ",
  str_guide_warn_19050101 = "อีเวนต์ \"ต้นไม้ ปลา กับช่วงเวลาสโลว์ไลฟ์\" เริ่มแล้ว! คุณพร้อมสำหรับการผจญภัยครั้งใหม่หรือยัง?",
  str_guide_warn_19050102 = "ในโหมด \"คุยกันสบาย ๆ\" เราจะเผชิญกับความท้าทายหลากหลาย",
  str_guide_warn_19050103 = "ตามรอยสัญญาณและหาสมบัติกับชับบ์กันต่อใน \"ค้นหาพิกัด ภาค 2\"!",
  str_guide_warn_19050104 = "เคลียร์ด่านต่าง ๆ ในอีเวนต์และใช้ปริซึม จะได้รับ \"ตั๋วสมาคมแอนเดอร์เซน\" ที่ใช้แลกของรางวัลต่าง ๆ ได้จาก \"สมาคมแอนเดอร์เซน\"",
  str_guide_warn_19050105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_19050106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_19050107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11000101 = "อีเวนต์ออกเดินทางยามรุ่งสางเริ่มแล้ว! คุณพร้อมสำหรับการผจญภัยครั้งใหม่หรือยัง?",
  str_guide_warn_11000102 = "เพื่อน ๆ แพ็งกาโลกลุ่มใหม่ของเราดูเหมือนจะเจอปัญหาบางอย่าง… ไปช่วยพวกเขาในโหมด \"ผู้มาเยือนสวนลอยฟ้า\" กันเถอะ!",
  str_guide_warn_11000103 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11000201 = "โจรกรรมใต้แสงจันทร์เปิดให้เล่นแล้ว! มาร่วมการผจญภัยกับแฟนท่อมธีฟส์เลย!",
  str_guide_warn_11000202 = "ใช้ปริซึมในเนื้อเรื่องหลักและด่านชิงทรัพยากรเพื่อรับคะแนนการแทรกซึม",
  str_guide_warn_11000203 = "แทรกซึมดันเจี้ยนจากที่นี่ ใช้คะแนนการแทรกซึมเพื่อเอาชนะศัตรูและรับรางวัลหลากหลายประเภท!",
  str_guide_warn_11000204 = "นี่คือด่านทดลองใช้แฟนท่อมธีฟส์ เล่นให้ผ่านด่านเพื่อรับรางวัลนะ",
  str_guide_warn_11000205 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11000206 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11000207 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11050101 = "อีเวนต์ลมฤดูร้อนและท่าเรือแห่งความหวังเริ่มแล้ว! คุณพร้อมสำหรับการผจญภัยครั้งใหม่หรือยัง?",
  str_guide_warn_11050102 = "ในโหมด \"เงาลึกลับตรอกพิศวง\" เราจะได้ท้าทายกับความยากลำบากหลายชุดด้วยกัน",
  str_guide_warn_11050103 = "ในโหมด \"คำทำนายใจเต้นรัว\" คุณจะได้เป็นนักสืบและสืบสวนคดีสิ่งของที่หายไปกับสาวสวยทั้งสาม!",
  str_guide_warn_11050104 = "เหรียญฮาร์เบอร์แฟร์ที่ได้รับจากการเคลียร์ด่านต่าง ๆ ในอีเวนต์และจากการใช้ปริซึมสามารถนำไปแลกของรางวัลได้จาก \"สตรีทแฟร์\"",
  str_guide_warn_11050105 = "ระหว่างผจญภัย ไปทดสอบฝีมือการทำอาหารของคุณได้ที่ \"รถอาหารจานด่วน\" เพื่อคว้ารางวัลมากมาย!",
  str_guide_warn_11050106 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11050107 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11050108 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11050201 = "ลูกค้าเริ่มต่อแถวกันแล้ว... เราต้องรีบทำอุด้งเพิ่มให้เร็วที่สุด!",
  str_guide_warn_11050202 = "ลูกค้าแต่ละคนจะสั่งอุด้งต่างกันไป เลือกส่วนผสมให้ถูกต้องด้วยนะ!",
  str_guide_warn_11050203 = "อารมณ์ของลูกค้าจะเริ่มแย่ลงในขณะที่รอ ยิ่งอารมณ์ดีมากเท่าไร เรตติ้งของคุณยิ่งดีขึ้นเท่านั้น!",
  str_guide_warn_11050204 = "ในการทำอุด้ง ก่อนอื่นต้องเลือกขนาดให้ถูกต้อง",
  str_guide_warn_11050205 = "จากนั้นก็เลือกน้ำซุป",
  str_guide_warn_11050206 = "เลือกส่วนผสมให้ถูกต้อง! ลำดับในการเลือกส่วนผสมและน้ำซุปไม่มีผลใด ๆ ตรงนี้!",
  str_guide_warn_11050207 = "แตะที่ลูกค้าเพื่อส่งอุด้งให้ แล้วออเดอร์ก็จะเสร็จสมบูรณ์!",
  str_guide_warn_11050208 = "การทำออเดอร์เสร็จติดต่อกันตามจำนวนที่กำหนดจะเกิดช่วงเวลา \"อุด้งไร้เทียมทาน\" ช่วยให้คุณทำออเดอร์ที่ตามมาได้ในไม่กี่วินาที!",
  str_guide_warn_11050209 = "นอกจากนี้คุณจะได้รับรางวัลโบนัสหลังจากทำออเดอร์ติดต่อกันอีกด้วย!",
  str_guide_warn_11050210 = "ไม่ต้องห่วงถ้าทำอุด้งผิด แค่แตะที่นี่เพื่อโยนทิ้งไป!",
  str_guide_warn_11050211 = "แตะที่นี่เพื่อหยุดทำอุด้งชั่วคราวแล้วพักสักหน่อย",
  str_guide_warn_11050212 = "เรื่องที่ต้องรู้เกี่ยวกับการทำอุด้งก็มีเท่านี้แหละ! กลับไปลุยงานกันต่อเถอะ!",
  str_guide_warn_11100101 = "อีเวนต์ลมฤดูร้อนและท่าเรือแห่งความหวังเริ่มแล้ว! คุณพร้อมสำหรับการผจญภัยครั้งใหม่หรือยัง?",
  str_guide_warn_11100102 = "ไพ่แปรสภาพที่ได้รับจากการเคลียร์ด่านเนื้อเรื่องหลักหรือด่านชิงทรัพยากรที่ใช้ปริซึม สามารถนำไปแลกของรางวัลได้จาก \"ราวแขวนหมวกแสนกล\"",
  str_guide_warn_11100103 = "ทุกคนในสวนลอยฟ้าอยากให้สร้างสระว่ายน้ำมาก ๆ กดเข้าไปที่ \"ว่ายน้ำกันเถอะ!\" ใน \"สารพันงานสวนลอยฟ้า\" ได้เลย!",
  str_guide_warn_11100104 = "ตามรอยสัญญาณและหาสมบัติกับชับบ์กันต่อใน \"ค้นหาพิกัด 3\"!",
  str_guide_warn_11100105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11100106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11100107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11200101 = "งานอำลา \"แดนมหัศจรรย์\" ของฉันได้เริ่มขึ้นแล้ว! การผจญภัยครั้งใหม่เริ่มต้นที่นี่และเดี๋ยวนี้",
  str_guide_warn_11200102 = "ใน No Man's Land เราจะเผชิญกับความท้าทายที่ยากลำบากมากมาย",
  str_guide_warn_11200103 = "ปลอกกระสุนเปล่าที่ได้รับจากการผ่านด่านกิจกรรมและการใช้จ่ายปริซึมสามารถใช้แลกรางวัลต่างๆ จากคลังเสบียงได้",
  str_guide_warn_11200104 = "ใน Street Errands เราจะสำรวจเมืองเพิ่มเติมและรวบรวมข้อมูลและข่าวสารตามท้องถนน",
  str_guide_warn_11200105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11200106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11200107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11200203 = "นี่เป็นภารกิจที่อันตรายและคุ้มค่า ไปกันเลย!",
  str_guide_warn_11200204 = "ลิฟต์กลางสามารถพาเราตรงไปยังส่วนลึกได้ แต่มีก๊าซอันตรายอยู่ด้านล่าง ดังนั้นจึงไม่สามารถสำรวจได้ในตอนนี้",
  str_guide_warn_11200205 = "นี่คือรายการของรางวัลจาก Illumina ยิ่งเราเสี่ยงมากเท่าไหร่ เราก็ยิ่งได้รับรางวัลมากขึ้นเท่านั้น",
  str_guide_warn_11200206 = "ยังไงก็ตาม มาดูกันว่าเราจะหาวิธีกำจัดก๊าซอันตรายได้หรือไม่!",
  str_guide_warn_11200207 = "สุริยุปราคายึดเครื่องช่วยหายใจทั้งหมดที่นี่ เปิดใช้งานเครื่องช่วยหายใจทั้งหมดเพื่อกำจัดก๊าซที่เป็นอันตรายและสำรวจชั้นถัดไปต่อไป",
  str_guide_warn_11200208 = "คุณจะต้องวาง Aurorian 5 ตัวที่เครื่องช่วยหายใจแต่ละเครื่องเพื่อเปิดใช้งาน เครื่องช่วยหายใจจะไม่ทำงานหากคุณถอนตัว Aurorians ออกก่อนที่การชำระล้างจะเสร็จสิ้นลงบนพื้น",
  str_guide_warn_11200209 = "เปิดใช้งานเครื่องช่วยหายใจทั้งหมดโดยตั้งทีม Aurorians หลายทีมเพื่อสำรวจต่อไป",
  str_guide_warn_11200210 = "Illumina ได้ให้ข้อมูลการสำรวจโดยละเอียดมากขึ้น แตะที่นี่เพื่อดู",
  str_guide_warn_11300101 = "กรี๊ดแปปเดียว! งานเริ่มแล้ว! การผจญภัยครั้งใหม่เริ่มต้นที่นี่และเดี๋ยวนี้",
  str_guide_warn_11300102 = "เหรียญโบราณที่ได้รับจากการผ่านด่านกิจกรรมและการใช้ปริซึมสามารถใช้แลกรางวัลต่างๆ จากห้องลับได้",
  str_guide_warn_11300103 = "ทุกคนใน Cloud Gardens หลงใหลในการสร้างฉากภาพยนตร์ใน Cloud Gardens! คุณสามารถตรวจสอบ Cloud Gardens ใหม่ Feat: ตั้งเวลาก่อสร้าง!",
  str_guide_warn_11300104 = "เริ่มถ่ายทำได้เลยเมื่อฉากจบ! คุณจะได้รับรางวัลอันน่าทึ่งจาก Chubbs หลังจากถ่ายทำภาพยนตร์!",
  str_guide_warn_11300105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11300106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11300107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11400102 = "ใช้ Prism เคลียร์ด่าน Main Story และ Resource Raid เพื่อรับ Scrap Parts และมอบให้ Axelia เพื่อประกอบเข้าด้วยกัน! คุณจะได้รับรางวัลอย่างมากมาย!",
  str_guide_warn_11400103 = "ทุกคนใน Cloud Gardens ดูเหมือนจะตื่นเต้นกับการจัดการแข่งขันตกปลา ดูกิจกรรม Cloud Gardens Feats ใหม่: จับได้ไม่ธรรมดา!",
  str_guide_warn_11400104 = "ทำสิ่งที่ท้าทายกับเพื่อนใหม่ของคุณให้สำเร็จเพื่อรับรางวัล Lumamber!",
  str_guide_warn_11400105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11400106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11400107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11500101 = "กิจกรรม The Starry Adventure: Heaven-Shaking Melody เริ่มขึ้นแล้ว! เราจะจัดคอนเสิร์ตที่ไม่เหมือนใครร่วมกับโกลดี้!",
  str_guide_warn_11500102 = "ใน Dreamy Nostalgia เราจะเผชิญกับความท้าทายที่ยากลำบาก",
  str_guide_warn_11500103 = "Goldie Merch ที่ได้รับจากการผ่านด่านกิจกรรมและการใช้ Prism สามารถใช้เพื่อแลกรับรางวัลต่างๆ จาก Brandy's Tabloids",
  str_guide_warn_11500104 = "ถ้ำ Eclipsite ลึกลับปรากฏขึ้นใกล้กับดินแดนลับ นักเดินเรือสามารถเอาชนะสิ่งกีดขวางได้โดยการเรียนรู้ทักษะการเรียนรู้ความสามารถพิเศษและใช้โบราณวัตถุเพื่อรับ Lumamber!",
  str_guide_warn_11500105 = "ใน Starlit Agency นักเดินเรือจะกลายเป็นตัวแทนของโกลดี้ จัดอบรมและจัดกิจกรรมส่งเธอขึ้นเวทีคอนเสิร์ตในที่สุด!",
  str_guide_warn_11500106 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11500107 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11500108 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11500201 = "เริ่มกันเลยเนวิเกเตอร์ นี่คือ Starlit Agency ที่ซึ่งเราจะฝึกไอดอลและจัดงานอีเวนต์เพื่อให้พวกเขาได้ขึ้นไปบนเวทีในที่สุด",
  str_guide_warn_11500202 = "หน่วยงานได้กำหนดวัตถุประสงค์บางอย่างให้กับเรา รางวัลมีให้หลังจากเสร็จสิ้น ความทรงจำจากการฝึกจะถูกบันทึกไว้ที่นี่ด้วย",
  str_guide_warn_11500203 = "หากคุณไม่พอใจกับการฝึกอบรม คุณสามารถกลับไปเลือกช่วงเวลาสำคัญเพื่อตัดสินใจอย่างอื่นได้",
  str_guide_warn_11500204 = "ได้เวลาเริ่มการฝึกแล้ว เนวิเกเตอร์!",
  str_guide_warn_11500301 = "นี่คือการนับถอยหลังจนถึงคอนเสิร์ต เหลืออีก 13 วัน! คุณได้ตัดงานของคุณออกไปแล้ว",
  str_guide_warn_11500302 = "แต่เราต้องมีแฟนเพลง 150,000 คนก่อนที่เราจะจัดคอนเสิร์ตได้",
  str_guide_warn_11500303 = "การเป็นไอดอลหมายถึงการฝึกฝนมากมาย มีโหมดการฝึกอบรมสามโหมดให้เลือก ให้แน่ใจว่าคุณอยู่ในความสงบเมื่อปาปารัซซี่ปรากฏตัว!",
  str_guide_warn_11500304 = "นี่คือทักษะไอดอลของฉัน โหมดการฝึกอบรมจะปรับปรุงให้ดีขึ้น",
  str_guide_warn_11500305 = "การจัดงานสามารถช่วยให้เรามีแฟนๆ เพิ่มขึ้นเพื่อให้บรรลุความต้องการสำหรับคอนเสิร์ต!",
  str_guide_warn_11500306 = "นี่คือรายการสิ่งที่ต้องทำของสัปดาห์นี้ คุณสามารถใช้เป็นข้อมูลอ้างอิงสำหรับการจัดกำหนดการได้ พูดคุยกับผู้คนระหว่างการฝึกอบรม และคุณอาจได้อะไรจากมัน",
  str_guide_warn_11500307 = "ข้อมูลที่เหลืออยู่ในคู่มือผู้ผลิต ปรึกษาได้ทุกเมื่อที่คุณต้องการ!",
  str_guide_warn_11500402 = "ไปที่ถ้ำเพื่อเริ่มความท้าทาย นอกจาก Lumamber แล้ว ผู้เล่นยังจะได้รับ EXP ความเชี่ยวชาญด้านความสามารถพิเศษเพื่อเพิ่มระดับความสามารถพิเศษของพวกเขา และรับคะแนนความเชี่ยวชาญด้านความสามารถพิเศษเพื่อให้แข็งแกร่งยิ่งขึ้น",
  str_guide_warn_11500403 = "ที่นี่คุณสามารถค้นหาภารกิจ Lair Reward การทำภารกิจให้สำเร็จจะทำให้คุณได้รับคะแนนความชำนาญพิเศษ",
  str_guide_warn_11500404 = "ใช้คะแนนความเชี่ยวชาญพิเศษเพื่อปลดล็อกทักษะความชำนาญพิเศษ อุปกรณ์ Caelesite พิเศษ และของที่ระลึกเพื่อทำให้การท้าทายที่ซ่อนง่ายขึ้น!",
  str_guide_warn_11500405 = "ทุกวัน Aurorians ทดลองที่แตกต่างกันจะพร้อมใช้งานใน Lair Challenges",
  str_guide_warn_11500406 = "คุณสามารถค้นหาข้อมูลเพิ่มเติมเกี่ยวกับ Lair ได้ที่นี่ รู้สึกอิสระที่จะเรียกดูได้ตลอดเวลา",
  str_guide_warn_11500601 = "ได้รับ EXP ความเชี่ยวชาญด้านความสามารถพิเศษเพียงพอเพื่อเพิ่มระดับความสามารถพิเศษของคุณและรับคะแนนความเชี่ยวชาญด้านความสามารถพิเศษ",
  str_guide_warn_11500602 = "ใช้แต้ม Talent Mastery เพื่อเปิดใช้งาน Talent Masteries เช่น Special Caelesite Gear เพื่อกระตุ้นทีมของคุณ",
  str_guide_warn_11500603 = "หลังจากใช้คะแนนความชำนาญความสามารถเพียงพอแล้ว วัตถุโบราณที่ทรงพลังอาจปรากฏขึ้นแบบสุ่มระหว่างการท้าทายถ้ำ",
  str_guide_warn_11500604 = "คุณสามารถสวมใส่ Special Caelestite Gear ได้ที่นี่ พวกเขาให้ทักษะที่ทรงพลังเพิ่มเติมในระหว่างการท้าทาย",
  str_guide_warn_11500605 = "หากคุณต้องการแก้ไข Talent Masteries ของคุณ คุณสามารถรีเซ็ต Talent Masteries และแต้ม Talent Mastery ที่เปิดใช้งานได้โดยไม่มีค่าใช้จ่าย",
  str_guide_warn_11500701 = "แตะที่นี่เพื่อดู Aurorians ในทีมของคุณ",
  str_guide_warn_11600101 = "อีเวนท์ Etched Upon the Ocean เริ่มขึ้นแล้ว! เข้าร่วมกลุ่มเพื่อนใหม่จาก Longzhou เพื่อค้นหาสมบัติที่สูญหายและเปิดเผยความลับลึกลับใน The Homecoming!",
  str_guide_warn_11600102 = "ใน Lost Ship At Sea เราจะเผชิญกับความท้าทายที่ยากลำบากมากมาย",
  str_guide_warn_11600103 = "Lin Guild Promissory Notes ที่ได้จากการผ่านด่านกิจกรรมและการใช้ Prism สามารถใช้เพื่อแลกรับรางวัลต่างๆ จาก The Docks",
  str_guide_warn_11600104 = "ในช่วงเทศกาลฤดูใบไม้ผลิ ชาวเมืองหลงโจวจะเตรียมงานฉลองอันหรูหราที่เรียกว่างานเลี้ยงอาหารค่ำแห่งความสามัคคี ช่วย Dantang ค้นหาสูตรอาหารเพื่อทำอาหารอร่อยเพื่อรับรางวัลต่างๆ รวมถึง Lumamber!",
  str_guide_warn_11600105 = "สมุดเยี่ยมนิรนามปรากฏขึ้นในกองถ่าย มันจะค่อยๆเติมความคิดเห็นที่ไม่ระบุตัวตน อ่านข้อความเหล่านี้เพื่อรับสคริปต์ภาพยนตร์ใหม่!",
  str_guide_warn_11600106 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11600107 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11600108 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11700101 = "กิจกรรม Fragmentary Vow เริ่มขึ้นแล้ว! เริ่มต้นการผจญภัยกับเพื่อนใหม่ของคุณจาก Courier Union ใน Mooncrown Pilgrimage",
  str_guide_warn_11700102 = "ในวิกฤต Feather Seal เราจะเผชิญกับความท้าทายที่ยากลำบาก",
  str_guide_warn_11700103 = "ขนนกหายากที่ได้รับจากการผ่านด่านกิจกรรมและใช้ปริซึมสามารถแลกเปลี่ยนเป็นรางวัลต่างๆ ได้ที่ Courier Express",
  str_guide_warn_11700104 = "ใน Sweet Delivery คุณจะได้สัมผัสกับชีวิตการทำงานที่ไปรษณีย์ของ Courier Union และแก้ไขวิกฤตความปรารถนาดีที่ไม่สิ้นสุดของ Navigator ได้ในเวลาเดียวกัน!",
  str_guide_warn_11700105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11700106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11700107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11700201 = "นี่คือข้อมูลการสั่งซื้อที่คุณได้รับในปัจจุบัน แตะรูปประจำตัวเพื่อเปลี่ยนคำสั่ง",
  str_guide_warn_11700202 = "ขอจบคำสั่งของลิลิก้าก่อน เธอต้องการเสื้อผ้า ขนมปัง และไวน์",
  str_guide_warn_11700203 = "ทางด้านขวา คุณจะพบรายการสินค้าทั้งหมด",
  str_guide_warn_11700204 = "ใส่ขนมปังลงในบรรจุภัณฑ์กันเถอะ!",
  str_guide_warn_11700205 = "ขณะที่แตะค้างไว้เพื่อลากสินค้า คุณยังสามารถแตะปุ่มเพื่อหมุน (ปุ่ม R) และพลิก (ปุ่ม T)",
  str_guide_warn_117002051 = "ขณะที่แตะค้างไว้เพื่อลากสินค้า คุณยังสามารถแตะปุ่มเพื่อหมุนและพลิก",
  str_guide_warn_11700206 = "หลังจากวางสินค้าตามคำสั่งซื้อทั้งหมดลงในบรรจุภัณฑ์แล้ว อย่าลืมแตะปุ่มบรรจุภัณฑ์เพื่อส่ง หากวางสินค้าไม่ครบทุกรายการในบรรจุภัณฑ์ ความคืบหน้าของการสั่งซื้อขั้นสุดท้ายจะได้รับผลกระทบ",
  str_guide_warn_11700207 = "แตะที่นี่เพื่อหยุดบรรจุภัณฑ์ชั่วคราว",
  str_guide_warn_11700208 = "ตอนนี้คุณรู้ทั้งหมดเกี่ยวกับกระบวนการเวิร์กโฟลว์แล้ว เรามาเก็บของกันต่อเลย!",
  str_guide_warn_11800101 = "กิจกรรม Confess Before the Gavel Strikes เริ่มขึ้นแล้ว! เริ่มต้นการผจญภัยกับทุกคนใน Hall of Justice ในช่วง Heartfelt Admissions",
  str_guide_warn_11800102 = "ใน \"เมื่อดอกไม้เหี่ยวเฉา\" เราจะเผชิญกับความท้าทายที่ยากลำบาก",
  str_guide_warn_11800103 = "ชิ้นส่วนพลาสเตอร์ที่ได้จากการผ่านด่านกิจกรรมและการใช้ปริซึมสามารถใช้แลกรางวัลต่างๆ จาก Evidence Collection ได้",
  str_guide_warn_11800104 = "ในช่วงกิจกรรม Love on Trial คุณจะได้ทำหน้าที่เป็นผู้ช่วยผู้พิพากษา รับฟังคดีที่อยู่ในมือและสืบสวนความจริงร่วมกับสมาชิกของแผนก Romance",
  str_guide_warn_11800105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11800106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11800107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11800201 = "ไม่ใช่ทุกคนที่จะได้ทำงานใน Hall of Justice ฉันจะใช้โอกาสนี้ให้เกิดประโยชน์สูงสุดถ้าฉันเป็นคุณ! แตะที่นี่เพื่อไปที่ Hall of Justice และดูว่ามีคดีใดบ้างรอคุณอยู่",
  str_guide_warn_11800202 = "คดีต่างๆ อาจมีจุดจบที่แตกต่างกันขึ้นอยู่กับการพิจารณาคดี หากคุณติดขัดระหว่างการสืบสวน คุณสามารถไปที่ Case Record และเลือกจุดเลือกเรื่องราวที่เกี่ยวข้องเพื่อทำการตัดสินใจต่าง ๆ ได้",
  str_guide_warn_11800203 = "คุณจะได้รับรางวัลอย่างแน่นอนสำหรับการทำงานหนักของคุณ ทำเรื่องราวให้เสร็จเพื่อปลดล็อกตอนจบและทำตามเงื่อนไขต่างๆ เพื่อรับตราและรางวัลที่นี่!",
  str_guide_warn_11800204 = "ฉันได้เขียนรายละเอียดทั้งหมดไว้ที่นี่ อย่าลืมอ่านอีกครั้งหากมีอะไรที่คุณยังไม่เข้าใจ",
  str_guide_warn_11800301 = "ว้าว! คุณได้เรียนรู้วิธีรวบรวมหลักฐานอย่างรวดเร็วแล้วหรือยัง? หลักฐานทั้งหมดนี้จะใช้เมื่อถึงเวลาแสดงหลักฐาน",
  str_guide_warn_11800401 = "ถูกตัอง. ถึงเวลาแสดงหลักฐาน! หลักฐานที่คุณรวบรวมได้จะแสดงอยู่ในรายการหลักฐาน อย่าลืมแตะเพื่อดูข้อมูลรายละเอียดเพิ่มเติม",
  str_guide_warn_11800402 = "การนำเสนอหลักฐานที่ไม่ถูกต้องอาจส่งผลต่อความสามารถของคุณและผลการพิจารณาคดี!\nลองเลือกหลักฐานที่ถูกต้องตามคำถามของแองเจิ้ล แตะที่นี่เพื่อโต้กลับ!",
  str_guide_warn_11800501 = "สมุดบันทึกของผู้พิพากษาเป็นสัญลักษณ์ของตัวตนของผู้พิพากษา คุณอยากรู้เกี่ยวกับเนื้อหาของมันหรือไม่?",
  str_guide_warn_11800502 = "โอ้! หลักฐานและรายละเอียดที่คุณรวบรวมจะถูกบันทึกไว้ที่นี่ ทำให้สะดวกมากในการตรวจสอบทุกอย่าง",
  str_guide_warn_11800503 = "สิ่งสำคัญคือต้องส่งเสริมสายสัมพันธ์ที่แน่นแฟ้นกับเพื่อนร่วมงานของคุณ เนื่องจากสายสัมพันธ์ระหว่างคุณกับเพื่อนร่วมงานอาจส่งผลต่อทิศทางของการพิจารณาคดีได้เช่นกัน ขอให้โชคดี!",
  str_guide_warn_11800601 = "ให้ฉันแนะนำกฎพื้นฐานของเกม! คุณต้องควบคุมตัวละครของคุณ ต่อสู้ผ่านด่านทั้งหมดจนกว่าคุณจะไปถึงบอสตัวสุดท้าย—Gronkenstein Ruu!",
  str_guide_warn_11800602 = "คุณสามารถแตะที่ปุ่มนี้เพื่อเปลี่ยนตัวละครได้ แต่พวกมันเหมือนกันทุกประการในแง่ของรูปแบบการเล่นจริง ๆ อย่าตัดสินกันแบบนั้น!",
  str_guide_warn_11800603 = "หากมีอะไรที่คุณยังไม่เข้าใจ คุณสามารถดูเอกสารได้ที่นี่",
  str_guide_warn_11800701 = "ด่านจะค่อยๆ ปลดล็อคเมื่อเวลาผ่านไป มาลองด่านแรกกัน!",
  str_guide_warn_11800702 = "ตราบใดที่คุณบรรลุเป้าหมายแรกของแต่ละด่าน คุณจะผ่านมันไปได้! คุณยังสามารถไปที่เป้าหมายทั้งหมดได้หากต้องการ!",
  str_guide_warn_11800703 = "เตรียมกระหึ่ม!",
  str_guide_warn_11800801 = "นี่ไง! คุณต้องทำให้ตัวละครของคุณก้าวไปข้างหน้าและพยายามอย่าให้ Eclipsites จับตัวคุณ! ให้ถึงเป้า!",
  str_guide_warn_11800802 = "มี Eclipsite ปกติอยู่ข้างหน้า! ฉวยจังหวะเหมาะๆ กระโดดเหยียบหัวมันซะ แล้วเกมจะจบลงสำหรับเจ้าหนูจอมกวน!",
  str_guide_warn_11800803 = "ตอนนี้! แตะปุ่มกระโดด!",
  str_guide_warn_118008031 = "ตอนนี้! แตะปุ่มกระโดด (T)!",
  str_guide_warn_11800804 = "ไม่เลว! คุณเป็นเกมเมอร์โดยกำเนิด!",
  str_guide_warn_11800805 = "ต่อไป เราจะต้องจัดการกับ Eclipsite ที่บินได้ หลังจากที่คุณกระเด็น คุณสามารถโจมตี Eclipsite ในตำแหน่งที่สูงขึ้นได้โดยใช้การกระโดดสองครั้ง!",
  str_guide_warn_11800806 = "ตอนนี้แตะ กระโดด!",
  str_guide_warn_11800807 = "แตะ Jump อีกครั้งเพื่อใช้การโจมตีการกระโดดสองครั้งของคุณ!",
  str_guide_warn_11800808 = "ตอนนี้คุณเชี่ยวชาญการควบคุมพื้นฐานของเกมอย่างเป็นทางการแล้ว! ลองผ่านด่านนี้ด้วยตัวเอง!",
  str_guide_warn_11800901 = "เนวิเกเตอร์ นกน้อยบอกฉันว่าคุณบ่นว่าด่านแรกง่ายเกินไปสำหรับคุณ!",
  str_guide_warn_11800902 = "ไม่ต้องกังวลไป ฉันมีสัตว์ประหลาดใหม่ที่ยากยิ่งกว่ารอคุณอยู่! Eclipsites หัวสวมหมวกเหล่านี้ต้องกระโดดสองครั้งก่อนที่คุณจะนับได้!",
  str_guide_warn_11800903 = "แตะ Jump แล้วกำจัดหมวกกันน็อคนั้น!",
  str_guide_warn_11800904 = "แตะ Dive ขณะอยู่บนอากาศเพื่อดำดิ่งลงไปอย่างรวดเร็วและกวาดล้างศัตรูด้านล่าง!",
  str_guide_warn_118009041 = "กด Dive (R) ขณะอยู่บนอากาศเพื่อพุ่งลงมาอย่างรวดเร็วและกวาดล้างศัตรูด้านล่าง!",
  str_guide_warn_11800905 = "เคล็ดลับ: การดำน้ำไม่ได้ดีแค่โจมตีศัตรูเท่านั้น แต่ยังทำให้คุณกระเด็นได้สูงขึ้นด้วย ดังนั้นคุณจึงสามารถเข้าถึงศัตรูได้เมื่อขึ้นไปบนฟ้า!",
  str_guide_warn_11800906 = "นี่เป็นคำแนะนำเล็กน้อยสุดท้ายที่ฉันจะให้คุณ! Eclipsites ที่มีหนามเหล่านี้ไม่สามารถถูกกระทืบได้ ดังนั้นเมื่อคุณเห็นพวกมัน ให้หลบพวกมันด้วยการกระโดดขึ้นไป! ตอนนี้มันขึ้นอยู่กับคุณแล้ว Navigator! ขอให้โชคดี!",
  str_guide_warn_11801001 = "อีเหี้ยยยย! ในที่สุดก็ถึงเวลาที่ฉันจะเข้าสู่เวทีกลาง! พบกับบอสตัวสุดท้าย—Gronkenstein Ruu!",
  str_guide_warn_11801101 = "นี่เป็นหนึ่งในเปลือกความรักของฉัน สัญญากับฉันว่าคุณจะไม่ใช้ Dive หรือ Double Jump เพื่อแยกมันออกจากกัน มิฉะนั้น ข้าจะเอาชนะเจ้าไม่ได้!",
  str_guide_warn_11801201 = "อ๊ะ! คุณเบี่ยงกระสุนของฉันและทำให้มันโดนฉันแทน!?",
  str_guide_warn_11801202 = "HP ของฉันเหลือเฟือ... ถ้าเธอยังโจมตีฉันด้วยกระสุน ฉันจะ... เฮ้ ทำไมเธอเก่งอย่างนี้ เนวิเกเตอร์!? ได้เลย! นำมาเลย!",
  str_guide_warn_11900101 = "อีเวนต์ Phantom of the Fire เริ่มขึ้นแล้ว! เตรียมสืบสวนคดีลึกลับและค้นหาความจริงเบื้องหลังกับเพื่อนๆ ของคุณที่ Umbraton ใน Manhunt: The Blue Flame!",
  str_guide_warn_11900102 = "ใน Dark Alley Encounters เราจะเผชิญกับความท้าทายที่ยากลำบากมากมาย",
  str_guide_warn_11900103 = "Case Records ที่ได้จากการผ่านด่านกิจกรรมและการใช้ Prism สามารถใช้เพื่อแลกรับรางวัลต่างๆ จาก Search & Seizure",
  str_guide_warn_11900104 = "ในโหมดลึกลับ Midnight Scribbles เราจะสำรวจความลับของสถานเลี้ยงเด็กกำพร้ากับ Hati หนุ่ม!",
  str_guide_warn_11900105 = "Crash & Burn กลับมาอีกครั้งในช่วงเวลาจำกัด! เตรียมตัวให้พร้อมเพื่อสัมผัสประสบการณ์การเล่นเกมที่ไม่เหมือนใคร!",
  str_guide_warn_11900106 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_11900107 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_11900108 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_11900201 = "ยินดีต้อนรับสู่ Midnight Scribbles! เรามาย้อนประสบการณ์ที่ผ่านมาในสถานเลี้ยงเด็กกำพร้ากันเถอะ!",
  str_guide_warn_11900202 = "แตะ Pick Up Crayon เพื่อเริ่ม!",
  str_guide_warn_11900203 = "หากคุณได้เริ่มการผจญภัยบนเส้นทางแห่งความทรงจำแล้ว แตะที่นี่เพื่อเดินทางต่อ!",
  str_guide_warn_11900204 = "เควสและรางวัลจะแสดงในอัลบั้ม และคุณยังสามารถดูตอนจบที่คุณทำสำเร็จได้ด้วย!",
  str_guide_warn_11900205 = "หากมีอะไรที่คุณยังไม่เข้าใจ คุณสามารถตรวจสอบข้อมูลได้ที่นี่",
  str_guide_warn_11900301 = "นี่คือแผนที่ของสถานเลี้ยงเด็กกำพร้า เราจะต้องสำรวจทุกที่เพื่อหาแรงบันดาลใจ!",
  str_guide_warn_11900302 = "แรงบันดาลใจที่คุณค้นหาจะแสดงที่นี่ พวกเขาจะมีประโยชน์ในภายหลัง!",
  str_guide_warn_11900303 = "มาทักทาย Miss Childminder กันเถอะ!",
  str_guide_warn_11900304 = "ถาม Miss Childminder เกี่ยวกับสถานที่นี้กันเถอะ!",
  str_guide_warn_11900401 = "คุณพร้อมที่จะคุยกับ Miss Childminder แล้วหรือยัง?",
  str_guide_warn_11900402 = "นี่คือรายการคำถามที่คุณสามารถถามได้ บางอย่างสามารถถามได้โดยตรง ในขณะที่บางอย่างสามารถถามได้หลังจากที่คุณค้นพบแรงบันดาลใจบางอย่างแล้วเท่านั้น!",
  str_guide_warn_11900403 = "ถามคำถามเกี่ยวกับสถานที่นี้!",
  str_guide_warn_11900404 = "ถามคำถามต่อไปในขณะที่คุณสำรวจเพื่อค้นหาแรงบันดาลใจ! คุณจะสามารถถามคำถามได้มากขึ้นเมื่อคุณพบแรงบันดาลใจมากขึ้น!",
  str_guide_warn_11900501 = "มันยุ่งมากที่นี่ ตรวจสอบทุกอย่างอย่างระมัดระวัง!",
  str_guide_warn_11900502 = "แสดงว่ามีวัตถุต้องสงสัยมากมายในห้องนี้!",
  str_guide_warn_11900503 = "ดูเหมือนว่าไม่มีเงื่อนงำ ขอเน้นสังเกตก่อน",
  str_guide_warn_11900504 = "มีถุงมือแปลกๆ อยู่คู่หนึ่งที่นี่ เข้าใกล้และตรวจสอบมัน!",
  str_guide_warn_11900601 = "มาดูแรงบันดาลใจที่เราพบและสรุปเหตุการณ์ในวันนี้กันก่อน!",
  str_guide_warn_11900602 = "ในการไขปริศนานี้ เราจำเป็นต้องมีแรงบันดาลใจสามส่วนเพื่อให้ได้คำตอบ",
  str_guide_warn_11900603 = "นี่คือแรงบันดาลใจทั้งหมดที่คุณมี คุณต้องเลือกสิ่งที่ถูกต้อง!",
  str_guide_warn_11900604 = "ประการแรก เกี่ยวกับสถานที่นี้... ดูเหมือนจะเป็นบ้านที่เต็มไปด้วยความรักและความเสน่หา?",
  str_guide_warn_11900605 = "หลังจากนั้นก็เห็นได้ชัดว่าเด็กๆมาอาศัยอยู่กับเราที่นี่ มีเด็กจำนวนมากในสถานเลี้ยงเด็กกำพร้า!",
  str_guide_warn_11900606 = "สุดท้ายแล้วเราจะดีหรือไม่ดี? แม้ว่าพวกเราบางคนจะเป็นคนดี แต่ดูเหมือนว่าจะมีคนร้ายอยู่บ้างที่นี่... เราจะต้องระบุพวกเขาทั้งหมดอย่างระมัดระวัง",
  str_guide_warn_11900607 = "ลองเรียงลำดับแรงบันดาลใจของคุณ!",
  str_guide_warn_11900608 = "ความสำเร็จ! นั่นคือสถานการณ์ในสถานเลี้ยงเด็กกำพร้า!",
  str_guide_name1 = "เซ็นโดย...",
  str_guide_name2 = "กรุณาพิมพ์ชื่อเล่นของคุณ",
  str_guide_name3 = "ยืนยัน",
  str_guide_name4 = "ชื่อเล่นของคุณไม่จำเป็นต้องเป็นชื่อจริง และไม่สามารถมีอักขระพิเศษได้ (สูงสุด 14 ตัวอักษร)",
  str_guide_create_no_name = "กรุณาสร้างชื่อเล่นก่อน",
  str_guide_ROLE_ERROR_DIRTY_NICK = "มีคำที่ไม่เหมาะสม",
  str_guide_ROLE_ERROR_CHANGE_NICK_INVALID = "ไม่สามารถใช้ตัวอักษรพิเศษได้",
  str_guide_ROLE_ERROR_CHANGE_NICK_LIMIT = "ความยาวชื่อเล่นสูงสุด 14 ตัวอักษร",
  str_guide_ROLE_ERROR_CHANGE_NICK_REPEAT = "คุณมีชื่อเล่นอยู่แล้ว",
  str_guide_ROLE_ERROR_CHANGE_NICK_SPE = "ไม่สามารถใช้ตัวอักษรพิเศษได้",
  str_guide_ROLE_ERROR_DUPLICATE_NICK = "ชื่อเล่นซ้ำกับผู้เล่นคนอื่น",
  str_guide_ROLE_ERROR_NEWSIGN_THE_SAME_AS_OLD = "ไม่มีการเปลี่ยนแปลงลายเซ็นใหม่",
  str_guide_ROLE_ERROR_NEWNAME_THE_SAME_AS_OLD = "ไม่มีการเปลี่ยนแปลงชื่อเล่นใหม่",
  str_guide_moren_name = "ผู้นำทาง",
  str_guide_team_limit_4001050 = "การผจญภัยครั้งนี้ต้องมีมิสบลังค์อยู่ด้วย กรุณาแตะที่การ์ดด้านบนเพื่อเปลี่ยนออโรเรียนที่จัดวางไว้แล้ว",
  str_guide_circle_click = "แตะที่ไหนก็ได้เพื่อเล่นต่อ",
  str_guide_circle_1_Lt = "ระบบป้องกันอัตโนมัติ (ADS) เป็นสิ่งที่สืบทอดจากยุคโบราณ มันทั้งทรงพลังและทำงานเองอัตโนมัติ!",
  str_guide_circle_1_LtT = "ระบบป้องกันอัตโนมัติ (ADS)",
  str_guide_circle_1_Rt = "ระบบ ADS จะหมุนอัตโนมัติรอบละหนึ่งครั้ง อาจเป็นการตั้งค่าเก่าแก่ตั้งแต่ยุคโบราณ",
  str_guide_circle_1_RtT = "กติกาการเดิน",
  str_guide_circle_1_Rb = "ระบบ ADS จะทำดาเมจกับเป้าหมายภายในสามช่องข้างหน้ามัน",
  str_guide_circle_1_RbT = "ระยะดาเมจ",
  str_guide_circle_2_Lt = "ครัชเชอร์เป็นอิคลิพไซท์ขนาดใหญ่ทั่วไปที่มี ATK และ HP สูงผิดปกติ",
  str_guide_circle_2_LtT = "ครัชเชอร์",
