  ["str_guide_circle_13-14_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_13-14_Rb"] = "ให้ความสำคัญกับการโจมตีดอกไม้ของ Diavola ก่อนเพื่อทำให้เป็นอัมพาตเพื่อสร้างความเสียหายให้กับมันอย่างปลอดภัย อย่าลืมดูแล Dawn Sprites ที่อัญเชิญมา",
  ["str_guide_circle_13-7-1_Lt"] = "สุริยุปราคาที่เกิดในสภาวะสุดขั้วของวันสิ้นโลก มันมีรูปร่างบิดเบี้ยวและสูญเสียความสามารถในการคิดอย่างชาญฉลาดไปนานแล้ว สิ่งที่เหลืออยู่คือความปรารถนาที่จะก้าวไปข้างหน้าและกลืนกินทุกสิ่งที่ขวางหน้า",
  ["str_guide_circle_13-7-1_LtT"] = "จอร์มังกานด์",
  ["str_guide_circle_13-7-1_Rt"] = "หัวของ Jormungand เป็นแกนหลักของการโจมตี มันสร้างความเสียหายอย่างมากแก่ศัตรูที่อยู่ใกล้หัวของมัน Jormungand ตายเมื่อหัวของมันมี HP เหลือ 0",
  ["str_guide_circle_13-7-1_RtT"] = "ลักษณะของหัวของ Jormungand",
  ["str_guide_circle_13-7-1_Rb"] = "ผู้เล่นต้องจำไว้ว่าต้องทำความเสียหายที่ศีรษะของ Jormungand จากระยะไกล Jormungand จะตายทันทีหากหัวของมันถูกกีดขวางจากสิ่งกีดขวางรอบด้าน",
  ["str_guide_circle_13-7-1_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_13-7-2_Lt"] = "ร่างกายของ Jormungand จำลองตัวเองเมื่อเวลาผ่านไปและยาวขึ้นทุกๆ รอบ ร่างกายของมันมีภูมิคุ้มกันต่อความเสียหายทั้งหมด",
  ["str_guide_circle_13-7-2_LtT"] = "ลักษณะของร่างกายของ Jormungand",
  ["str_guide_circle_13-7-3_Lt"] = "หางของ Jormungand คือจุดอ่อนของมัน ความเสียหายทั้งหมดที่ทำกับหางจะถูกโอนไปยังส่วนหัว และคุณจะสร้างความเสียหายได้มากขึ้น",
  ["str_guide_circle_13-7-3_LtT"] = "ลักษณะของหางของ Jormungand",
  ["str_guide_circle_14-9-1_LtT"] = "โคมไฟวิญญาณ",
  ["str_guide_circle_14-9-1_Lt"] = "Eclipsite ที่ดัดแปลงโดย Asmodeus ความต้องการของมันถูกควบคุมโดย Asmodeus ดังนั้นมันจึงเชื่อฟังทุกคำสั่งของเธอ",
  ["str_guide_circle_14-9-1_RtT"] = "ลักษณะของมอนสเตอร์ I",
  ["str_guide_circle_14-9-1_Rt"] = "หาก Lantern Spirit สามารถเทเลพอร์ตผ่าน Aurorians เมื่อทำการโจมตี มันจะสร้างห่วงโซ่ที่ทำให้ทั้งความเสียหายที่ได้รับและ HP ที่ฟื้นคืนมาถูกแบ่งปันระหว่างฝ่ายที่เชื่อมโยง",
  ["str_guide_circle_14-9-1_RbT"] = "เทเลพอร์ต",
  ["str_guide_circle_14-9-1_Rb"] = "Lantern Spirit สามารถเทเลพอร์ตได้หากสามารถผ่านกระเบื้องที่ Aurorian เปิดอยู่และย้ายไปที่กระเบื้องอีกด้านหนึ่ง",
  ["str_guide_circle_14-9-2_LtT"] = "โซ่",
  ["str_guide_circle_14-9-2_Lt"] = "เมื่อฝ่ายใดฝ่ายหนึ่งเชื่อมต่อกันด้วยสายโซ่ได้รับความเสียหายหรือฟื้นฟู HP อีกฝ่ายจะได้รับความเสียหายเท่ากันหรือฟื้นฟู HP เท่ากัน",
  ["str_guide_circle_14-9-2_RtT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_14-9-2_Rt"] = "รักษาระยะห่างจาก Lantern Spirit เพื่อทำลายโซ่",
  ["str_guide_circle_14-9-2_RbT"] = "เอาชนะหรือเสมอพวกเขา!",
  ["str_guide_circle_14-9-2_Rb"] = "การเอาชนะหรือดึงวิญญาณโคมไฟเข้าหาตัวคุณก็เป็นหนทางหนึ่งในการหลุดพ้นจากโซ่ตรวนที่เชื่อมโยงคุณ",
  ["str_guide_circle_14-14-1_LtT"] = "แอสโมเดอุส",
  ["str_guide_circle_14-14-1_Lt"] = "เจตภูตผู้ทรงพลังมีความสามารถที่น่าสะพรึงกลัวในการมองทะลุความปรารถนาทั้งหมดของฝ่ายตรงข้ามและสนุกกับการบงการพวกมัน",
  ["str_guide_circle_14-14-1_RtT"] = "ลักษณะของสุริยุปราคา",
  ["str_guide_circle_14-14-1_Rt"] = "เมื่อเข้าสู่สนามพลัง Asmodeus จะแยกตัวเป็นสอง โคลนหนึ่งไม่สามารถถูกสกิลโจมตี และอีกโคลนหนึ่งไม่สามารถถูกโจมตีทั่วไป ทั้งสองตัวเชื่อมต่อกันด้วยห่วงโซ่แห่งความปรารถนา",
  ["str_guide_circle_14-14-1_RbT"] = "ห่วงโซ่แห่งความปรารถนา",
  ["str_guide_circle_14-14-1_Rb"] = "เมื่อ Asmodeus ใด ๆ ที่เชื่อมต่อด้วยห่วงโซ่แห่งความปรารถนาได้รับความเสียหายหรือฟื้นคืนพลังชีวิต อีก Asmodeus หนึ่งจะได้รับผลกระทบเดียวกัน หลังจาก Asmodeus ดำเนินการ พื้นที่มืด (Dark Regions) จะเกิดขึ้นใต้ห่วงโซ่แห่งความปรารถนา",
  ["str_guide_circle_14-14-2_LtT"] = "แอสโมเดอุส",
  ["str_guide_circle_14-14-2_Lt"] = "Asmodeus นี้มีภูมิคุ้มกันต่อความเสียหายจากการโจมตีปกติและมีการโจมตีระยะไกลที่ทรงพลัง",
  ["str_guide_circle_14-14-3_RtT"] = "แอสโมเดอุส",
  ["str_guide_circle_14-14-3_Rt"] = "Asmodeus นี้มีภูมิคุ้มกันต่อความเสียหายจากทักษะและเชื่อมโยงตัวเองกับ Aurorians ที่เธอโจมตีด้วย Chain of Nightmares",
  ["str_guide_circle_14-14-3_RbT"] = "ห่วงโซ่แห่งฝันร้าย",
  ["str_guide_circle_14-14-3_Rb"] = "Aurorians ที่เชื่อมต่อกันด้วย Chain of Nightmares จะได้รับความเสียหายทุกช่องที่พวกเขาสำรวจ การออกจากระยะของ Chain of Nightmares จะทำให้มันพัง",
  ["str_guide_circle_14-7_LtT"] = "เซอร์ริทัส",
  ["str_guide_circle_14-7_Lt"] = "Eclipsite ใหม่ที่พบในระหว่างการสำรวจดูเหมือนจะแตกต่างจาก Eclipsite ที่ทรงพลัง เว้นแต่จะบ้าคลั่งกว่าและทำลายล้างได้มากกว่า",
  ["str_guide_circle_14-7_RtT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_14-7_Rt"] = "Cerritus โจมตี Aurorians โดยการพุ่งชนพวกเขา และมีความสามารถอันทรงพลังในการเรียก Pebbles และเปลี่ยนภูมิประเทศ Cerritus แข็งแกร่งขึ้นเมื่อการต่อสู้ดำเนินไป การโจมตีที่ไม่ฆ่า Cerritus มีแต่จะทำให้แข็งแกร่งขึ้น! ทุกสองสามรอบ Cerritus คำรามด้วยความโกรธและเข้าสู่สภาวะบ้าคลั่ง",
  ["str_guide_circle_14-7_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_14-7_Rb"] = "ให้ความสนใจกับตำแหน่งสัมพัทธ์ของคุณจากศัตรู ใช้ทักษะในเวลาที่เหมาะสมเพื่อยุติการต่อสู้อย่างรวดเร็ว",
  str_guide_circle_N24_petTry_LtT = "ฮีลลิ่งออร์บ",
  str_guide_circle_N24_petTry_Lt = "วัตถุอัญเชิญของ Axelia เธอรักษาตัวเองเมื่อเธอดูดซับสิ่งนี้ด้วย Active Skill ของเธอหรือเมื่อทีมผ่านมัน แปลงร่างหลังจากมีอยู่ 2 รอบ ให้ผลการรักษาเพิ่มเติม",
  str_guide_circle_N24_petTry_Lt_1 = "วัตถุอัญเชิญของ Axelia เธอรักษาตัวเองเมื่อเธอดูดซับสิ่งนี้ด้วย Active Skill ของเธอหรือเมื่อทีมผ่านมัน",
  ["str_guide_circle_N25_1-4_LtT"] = "เวนเม็กซ์",
  ["str_guide_circle_N25_1-4_Lt"] = "กล่าวกันว่าเป็นญาติห่างๆ ของสายพันธุ์ Eclipsite ที่สามารถระเบิดตัวเองได้ ยกเว้นสายพันธุ์นี้สามารถปล่อยลูกบอลเมือกพิษ สร้างความเสียหายอย่างมากต่อสิ่งมีชีวิต",
  ["str_guide_circle_N25_1-4_LbT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N25_1-4_Lb"] = "พ่นพิษเป็นเส้นตรงหรือในตำแหน่งของ Aurorian สร้างพิษให้กับศัตรูและพันธมิตรทั้งหมดที่อยู่ในระยะของพิษ",
  ["str_guide_circle_N25_1-4_RtT"] = "กลยุทธ์",
  ["str_guide_circle_N25_1-4_Rt"] = "บางทีคุณอาจใช้พิษของมันเพื่อทำให้ศัตรูตัวอื่นต้องทนทุกข์ทรมาน",
  ["str_guide_circle_N25_1-16_RtT"] = "ผู้ท่องความฝัน",
  ["str_guide_circle_N25_1-16_Rt"] = "ว่ากันว่ามันคือ \"พี่ชาย\" ของแฟนท่อมในรัตติกาลนิรันดร์ มันสามารถใช้กลวิธีต่าง ๆ ตามช่วงเวลาของวันและจัดการได้ยากนัก",
  ["str_guide_circle_N25_1-16_LtT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N25_1-16_Lt"] = "มีความสามารถในการโจมตี Aurorians จากระยะไกลและสามารถเปิดการโจมตีแบบเต็มหน้าจอได้ สามารถเรียกภูตผีที่ล้อมรอบ Aurorians แต่ไม่สามารถโจมตีได้",
  ["str_guide_circle_N25_1-16_LbT"] = "กลยุทธ์",
  ["str_guide_circle_N25_1-16_Lb"] = "พึ่งพาการเคลื่อนไหวที่ว่องไวเพื่อหลีกเลี่ยงการถูกล้อมรอบด้วย Phantoms",
  ["str_guide_circle_N25_2-4_LtT"] = "โคเซ็น",
  ["str_guide_circle_N25_2-4_Lt"] = "มีความสามารถที่โดดเด่นในการผสมผสานเข้ากับสภาพแวดล้อม บางครั้งมันก็ดูเหมือนกับดักธรรมดา อย่างไรก็ตาม เมื่อมันเปิดเผยตัว มันก็ระเบิดอาละวาดอย่างอาฆาต",
  ["str_guide_circle_N25_2-4_LbT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N25_2-4_Lb"] = "มักจะซ่อนอยู่ใน Crud เมื่อการนับถอยหลังสิ้นสุดลง มันจะปรากฏตัวขึ้นและโจมตีพวกออโรเรียน",
  ["str_guide_circle_N25_2-4_RtT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_N25_2-4_Rt"] = "การรีเซ็ตไทล์ที่ Crud อยู่จะเป็นการลบ Crud และทำให้ Cozen ปรากฏขึ้น",
  ["str_guide_circle_N26_1-12_RtT"] = "โหย",
  ["str_guide_circle_N26_1-12_Rt"] = "เมื่อเป็นผู้นำของงู เขาถูกกดขี่โดย Aurorians เพื่อใช้เป็นเครื่องมือในการนำทาง ปีแห่งความเกลียดชังที่เพิ่มขึ้นทำให้เขากลายเป็นศัตรูที่ทรงพลัง",
  ["str_guide_circle_N26_1-12_LtT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N26_1-12_Lt"] = "มีความสามารถทางเวทมนตร์ที่ทรงพลังและสามารถควบคุมกระสุนเพื่อสร้างความเสียหายแก่ศัตรู",
  ["str_guide_circle_N26_1-12_LbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_N26_1-12_Lb"] = "ล้าง \"Word\" และแบบจำลองในสนามโดยเร็วที่สุดเพื่อหลีกเลี่ยงความเสียหายหนัก",
  ["str_guide_circle_N27_1-1_RtT"] = "ผู้ช่วยที่ไม่มีเสียง",
  ["str_guide_circle_N27_1-1_Rt"] = "เป็นไปได้ว่า \"ผู้ให้คำปรึกษา\" ของ Eclipsite บางประเภทเห็นว่าพวกเขาทั้งสองรักษา Eclipsites อื่นได้อย่างไร ข้อแตกต่างคือ Eclipsite นี้มีแนวโน้มที่จะอยู่ใกล้พันธมิตรที่ตัวใหญ่กว่าเพื่อใช้ประโยชน์สูงสุดจากเอฟเฟกต์พิเศษของสกิล",
  ["str_guide_circle_N27_1-1_LtT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N27_1-1_Lt"] = "สามารถฟื้นฟู HP ของ Eclipsites อื่นได้ ยิ่งกระเบื้องครอบครองโดย Eclipsites อื่น ๆ ภายในระยะทักษะของ Aphonic Assistant มากเท่าไหร่ ผลของการรักษาก็จะยิ่งแข็งแกร่งขึ้นเท่านั้น",
  ["str_guide_circle_N27_1-1_LbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_N27_1-1_Lb"] = "จัดลำดับความสำคัญในการจัดการกับ Aphonic Assistant และป้องกันไม่ให้ Aphonic Assistant รักษา Eclipsites อื่น!",
  ["str_guide_circle_N27_1-12_LtT"] = "หนอนทรายสีชมพู",
  ["str_guide_circle_N27_1-12_Lt"] = "หนอนทรายหายากที่มีถิ่นกำเนิดในทะเลทราย Rediesel มันถูกปกคลุมด้วยเกล็ดสีชมพูเนื่องจากการกลายพันธุ์ที่ไม่เหมือนใคร ทำให้มันมีพลังและดุร้ายกว่าหนอนทรายตัวอื่นๆ",
  ["str_guide_circle_N27_1-12_RtT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N27_1-12_Rt"] = "เจาะดินเพื่อหาตำแหน่งของเป้าหมาย แล้วระเบิดออกในที่โล่ง พ่นทรายสีดำโจมตีเป้าหมายที่อยู่ด้านหน้า",
  ["str_guide_circle_N27_1-12_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_N27_1-12_Rb"] = "การหลีกเลี่ยงการโจมตีของหนอนทรายสีชมพูอาจเป็นเรื่องยุ่งยาก! ให้ความสนใจกับสถานะของตัวเองตลอดเวลาและยุติการต่อสู้ให้เร็วที่สุด!",
  ["str_guide_circle_N27_2-4-1_RbT"] = "เครนกระดาษ",
  ["str_guide_circle_N27_2-4-1_Rb"] = "นกกระเรียนกระดาษสามารถวางบนกระเบื้อง Abyssal และแปลงกระเบื้องข้างใต้เป็นกระเบื้องสี นกกระเรียนกระดาษจะหายไปหลังจากที่ทีมเดินผ่านพวกมัน",
  ["str_guide_circle_N27_2-4-2_RbT"] = "ออโรเรียนผู้ช่วย",
  ["str_guide_circle_N27_2-4-2_Rb"] = "Pasolo สามารถวางนกกระเรียนกระดาษบนแผ่นกระเบื้องเพื่อช่วยให้ทีมของเธอเอาชนะสถานการณ์ที่ยากลำบากได้ อย่าลืมใช้ตัวช่วยทักษะของ Pasolo ทุกรอบ!",
