  ["str_guide_circle_N30_15-2_LbT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N30_15-2_Lb"] = "ใช้การโจมตีระยะไกลมากขึ้น เมื่อการต่อสู้ดุเดือด พุ่งเข้าหาศัตรูและต่อสู้ระยะประชิดเพื่อกำจัดพวกมันให้เร็วที่สุด",
  ["str_guide_circle_N30_15-2_RbT"] = "เข้ามา!",
