  ["str_guide_circle_N30_15-9_Lt"] = "หุ่นยนต์ต่อสู้ที่พัฒนาโดย Illumina มันทำงานได้ดีมากในการทดสอบภายใน แต่ยังไม่ได้รับการทดสอบในการต่อสู้จริง",
  ["str_guide_circle_N30_15-9_LtT"] = "ช่างเจาะ",
