  ["str_guide_circle_N30_15-9_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_N30_15-9_Rb"] = "เมื่อมีฟิลด์สนับสนุนน้อยลงในฟิลด์นี้ Driller จะขุดฟิลด์สนับสนุนเพิ่มเติม",
  ["str_guide_circle_N30_15-9_RbT"] = "หมายเหตุ",
  ["str_guide_circle_N30_15-9-2_Lt"] = "Energy Fields เป็นกระเบื้องที่มีพลังงานเต็มที่ซึ่งสามารถใช้ประกอบแท่นเจาะได้ มันหยุดการผ่านของหน่วยบนพื้นเมื่อมีอยู่",
  ["str_guide_circle_N30_15-9-2_LtT"] = "สนามพลังงาน",
  ["str_guide_circle_N30_15-9-2_Rb"] = "หากมีสนามพลังงาน 6 แห่งในสนามรบเมื่อ Driller ดำเนินการ Driller จะเปิดใช้ทักษะพิเศษโดยสร้างแท่นเจาะ",
  ["str_guide_circle_N30_15-9-2_RbT"] = "ชิ้นส่วนที่จำเป็นสำหรับการประกอบ",
  ["str_guide_circle_N30_16-14_Lt"] = "ในฐานะหนึ่งในเจตภูตที่ทรงพลังที่สุด เขาโจมตีด้วยกำลังทั้งหมดที่มีเมื่อสถานะของเขาถูกคุกคาม",
