  ["str_guide_circle_N30_16-14_Lb"] = "แผ่นกระเบื้องพังทลายลงหลังจากที่ชาวออโรเรียนเคลื่อนผ่าน เมื่อกระเบื้องในสนามรบไม่เพียงพอ ฟิเจอรัลด์จะปลดปล่อยพลังของเขาเพื่อเปลี่ยนรูปร่างของพื้นที่และสร้างความเสียหาย",
  ["str_guide_circle_N30_16-14_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_N30_16-14_Rt"] = "วางแผนเส้นทางของคุณให้ดีเพื่อลดจำนวนครั้งที่คุณได้รับความเสียหายเมื่อฟิเจอรัลด์เปลี่ยนรูปร่างของพื้นที่",
  ["str_guide_circle_N30_16-14_RtT"] = "กลยุทธ์รับมือ",
