  str_guide_circle_N30_tower10_LbT = "ลักษณะของศัตรู",
  str_guide_circle_N30_tower10_RbT = "ระวัง!",
  str_guide_circle_N30_tower10_Lt = "ผู้พิทักษ์โบราณที่สร้างขึ้นเพื่อจุดประสงค์เดียวในการปกป้องความลับของดินแดนนี้ การโจมตีของมันยากที่จะหลบหนี และยังมีการฟื้นฟูตัวเองอย่างเหลือเชื่อเพื่อให้มันทำงานได้ตลอดไป คงไม่มีใครอยากเผชิญหน้าเพียงลำพัง",
  str_guide_circle_N30_tower10_Lb = "สร้างเขตป้องกันภายใน 2 กลุ่มรอบๆ ตัวมันเองทุกรอบ Aurorians ภายในเขตป้องกันจะได้รับความเสียหายเพิ่มเติมเมื่อใดก็ตามที่พวกเขาโจมตีหรือเคลื่อนไหว หาก Mechanical Huntsman อยู่ยงคงกระพันเมื่อดำเนินการ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP เต็ม",
  str_guide_circle_N30_tower10_Rb = "เมื่อ Mechanical Huntsman เข้าสู่สภาวะไร้เทียมทาน มันจะปล่อยการโจมตีที่อันตรายอย่างยิ่ง ซึ่งจะลดศัตรูทั้งหมดในเขตป้องกันเหลือ 1 HP ในรอบถัดไป",
  str_guide_circle_N30_tower10_3_LtT = "เบนนูการ์เดียน",
  str_guide_circle_N30_tower10_3_Lt = "ผู้พิทักษ์โบราณที่อาศัยอยู่ในส่วนลึกของ Secret Territory ตื่นขึ้นเนื่องจากการรบกวนจากผู้บุกรุกบ่อยครั้ง แม้แต่ Eclipsites ก็ยังกลัวความสามารถอันทรงพลังของมัน เดินไปรอบ ๆ สนามรบอย่างไร้จุดหมาย",
  str_guide_circle_N30_tower10_3_LbT = "ลักษณะของศัตรู",
  str_guide_circle_N30_tower10_3_Lb = "มีพลังอันยิ่งใหญ่ สะสม Fury เมื่อถูกโจมตี เมื่อ Fury ถึงระดับหนึ่ง จะเข้าสู่สถานะ Enraged ลดความเสียหายที่ได้รับและร่ายทักษะที่ทรงพลังเพิ่มเติม หาก Bennuguardian อยู่ยงคงกระพันเมื่อดำเนินการ มันจะใช้พลังงานฟื้นฟูเพื่อฟื้นฟู HP เต็ม",
  str_guide_circle_N30_tower10_3_RbT = "ระวัง!",
  str_guide_circle_N30_tower10_3_Rb = "ตรวจสอบความโกรธของ Bennuguardian ตลอดเวลาและดำเนินการอย่างระมัดระวัง!",
  ["str_guide_circle_15-14_LtT"] = "ทดสอบสถานะ Helios",
  ["str_guide_circle_15-14_Lt"] = "หลังจากอยู่คนเดียวมานานกว่าทศวรรษใน Dark Zone ทหาร Illumina คนนี้ได้ลืมทุกอย่างยกเว้นการต่อสู้ สิ่งที่น่ากลัวคือเขาแข็งแกร่งขึ้นในการต่อสู้หลังจากถูกดัดแปลงโดยใครบางคน...",
  ["str_guide_circle_15-14_RtT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_15-14_Rt"] = "เอนทิตีที่มีความสามารถในการต่อสู้ที่แข็งแกร่งและสะสมรอยฟกช้ำเมื่อได้รับความเสียหาย เมื่อการโจมตีของเขาพลาดเป้า เครื่องหมาย Terror Mark จะถูกปล่อยออกมาในสนาม ทักษะของ Helios นั้นทรงพลังยิ่งขึ้นด้วย Terror Mark ทุกอันบนสนาม",
  ["str_guide_circle_15-14_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_15-14_Rb"] = "จดตำแหน่งที่จะหลีกเลี่ยงการโจมตีของ Helios!",
