  str_guide_circle_621_Rt = "เมื่อเชื่อมต่อกับกระเบื้องอื่น ๆ กระเบื้อง 4 อันที่อยู่รอบ ๆ เป็นรูปกากบาทจะถูกแปลงเป็นสีเดียวกัน",
  ["str_guide_circle_N30_16-9_Lt"] = "Eclipsite พิเศษนี้มีลักษณะคล้ายแมงมุมและได้เรียนรู้พฤติกรรมของกลุ่มแมงมุมในเส้นทางวิวัฒนาการของมัน มันซ่อนตัวอยู่ในความมืดที่แสงแดดส่องไม่ถึง",
