  ["str_guide_circle_N30_16-9_Lb"] = "มีความสามารถในการสืบพันธุ์ที่แข็งแกร่ง มันสานใยแมงมุมในสภาพแวดล้อมการล่าสัตว์",
  ["str_guide_circle_N30_16-9_LbT"] = "ลักษณะของมอนสเตอร์",
  ["str_guide_circle_N30_16-9_Rt"] = "มุ่งความสนใจของคุณไปที่การล้างใยและกำจัดไข่แมงมุมที่เรียกออกมาของ Spider Queen และ Spider Hatchlings ให้เร็วที่สุดเท่าที่จะทำได้",
  ["str_guide_circle_N30_16-9_RtT"] = "กลยุทธ์รับมือ",
