  ["str_guide_circle_N30_16-3_LtT"] = "ยอดทหารอิลลูมินา",
  ["str_guide_circle_N30_16-3_Lb"] = "ทุกครั้งที่ศัตรูใช้ Active Skill จะเลื่อน 1 ช่องไปหาศัตรูทันทีและโจมตี",
  ["str_guide_circle_N30_16-3_LbT"] = "ความสามารถในการตอบโต้",
  ["str_guide_circle_N30_16-3_Rt"] = "สะสมรอยฟกช้ำเมื่อได้รับความเสียหาย หากผู้เล่นไม่ทำดาเมจกับยูนิตนี้ในระหว่างรอบนี้ รักษารอยฟกช้ำทั้งหมดทันทีเพื่อฟื้นฟู HP",
