  str_guide_warn_12000101 = "กิจกรรม Illumination's Descent กำลังดำเนินการอยู่! ในช่วงระยะเวลากิจกรรม Illumina Supply Center จะเปิดให้กับ Navigators ทุกคน!",
  str_guide_warn_12000102 = "บัตรเสบียงที่ได้รับจากการใช้ปริซึมสามารถแลกเปลี่ยนเป็นรางวัลต่างๆ ได้ที่ Illumina Supply Center",
  str_guide_warn_12000103 = "เข้าสู่เครื่องจำลองการฝึกซ้อมทางทหารแบบใหม่ของ Gronru เพื่อเข้าร่วมการฝึกที่ครอบคลุมกับ Aurorians ของคุณ!",
