  ["str_guide_circle_N31_1-16_Lb"] = "เลือกกลยุทธ์การดำเนินการที่แตกต่างกัน เช่น จะใช้การโจมตีปกติหรือทักษะกับ Joshua: Tainted Soul ในรอบปัจจุบันตามผลของ Phantom Crystal",
