  str_guide_warn_6012210 = "นักเดินเรือสามารถแลกเปลี่ยน Forgotten Utterances และ Forgotten Whispers ที่ Exiled Harborage เป็น Solamber, Aurorians และ Star Flares",
  str_guide_warn_12200201 = "ฮะ? ฉันอยู่ที่ไหน? นั่นคือ... คริสตัลแห่งความทรงจำชั่วนิรันดร์อีกชิ้นหนึ่งหรือ?",
  str_guide_warn_12200202 = "สุดท้ายเราออกไม่ได้เหรอ...? ใช้ได้! ท่องคาถาการเดินทางข้ามเวลาออกมาดัง ๆ แล้วแตะที่นี่!",
  str_guide_warn_12200301 = "จุ๊ๆ... ดูเหมือนมีใครบางคนกำลังพูดอยู่ใกล้ๆ อะแฮ่ม ฉันไม่ได้แอบฟังนะ! เรียกว่า... รวบรวมข้อมูล!",
  str_guide_warn_12200401 = "ดู? ฉันรู้ว่าฉันพูดถูก เราได้รับข้อมูลที่น่าเหลือเชื่อบางอย่าง! อะไร คุณจำไม่ได้ทุกอย่าง? จากนั้นใส่ข้อมูลที่เรารวบรวมไว้ที่นี่!",
  str_guide_warn_12200402 = "ดูข้อมูลทั้งหมดอยู่ที่นี่ ตอนนี้คุณไม่จำเป็นต้องกังวลเกี่ยวกับการลืมของ! ให้ความสนใจกับทุกสิ่งรอบตัวคุณและเติมเต็มช่องว่างนี้ให้เต็ม",
  str_guide_warn_12200101 = "Edge of Collapse เริ่มขึ้นแล้ว! ใน The Divergence เราจะตรวจสอบความลึกลับของ Crystal of Eternal Memory!",
  str_guide_warn_12200102 = "เราจะเผชิญกับความท้าทายที่ยากลำบากในโลกแห่งภาพลวงตาที่แตกสลาย",
  str_guide_warn_12200103 = "Crystal Teardrops ที่ได้จากการผ่านด่านกิจกรรมและการใช้ Prism สามารถแลกเป็นรางวัลต่างๆ ได้ที่ Hall of Remembrance",
  str_guide_warn_12200104 = "อย่าลืมล็อกอินเข้าเกมทุกวันเพื่อรับรางวัล Wistful Musing",
  str_guide_warn_12200105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_12200106 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_circle_N33_15_Lt = "ผีเสื้อที่หายากมาก ซึ่งมีข่าวลือว่าปรากฏตัวใกล้ หุบเขาดีนูออ มันเป็นสิ่งมีชีวิตที่ขี้เกรงใจ มีประสาทสัมผัสที่คมบางมาก พลังรบของเทพีดีนูออผู้ใหญ่ไม่ควรถูกมองข้าม",
  str_guide_circle_N33_15_LtT = "เทพีดีนูโอ",
