  str_guide_circle_N33_15_Rt = "เลือกเส้นทางของคุณอย่างรอบคอบเพื่อป้องกันให้เทพีดีนูโอ้สามารถปล่อยเชื้อให้กับสายพันธุ์เซเดเซียน เอนแชนท์วีด ทำให้มันกลายเป็นมากขึ้น",
