  str_guide_circle_chapter18_14_Rb = "เข้าร่วมการโจมตีอย่างเข้มข้นเพื่อทำให้เครื่องยนต์เสื่อมโทรม VII หยุดชะงัก ล่าช้าการโจมตีประตูของเขตป้อมอิลลูมินา",
  str_guide_circle_chapter18_14_RbT = "กลยุทธ์รับมือ",
  str_guide_circle_chapter18_14_Rt = "เดิมเป็นหุ่นยนต์ต่อสู้ขนาดยักษ์ที่สร้างโดย Illumina หลังจากที่นักบินสูญเสียสติจากการปนเปื้อนด้วยโคลน มันกลายเป็นความขัดแย้งที่น่ากลัวที่สุด",
  str_guide_circle_chapter18_14_RtT = "เครื่องยนต์เสียหาย VII",
  str_guide_warn_80010102 = "คุณเท่านั้นที่จะเข้าไปในความฝันของอีฟได้...",
  str_guide_warn_80010103 = "ทำภารกิจที่มีรายละเอียดในชิ้นส่วนแห่งความทรงจำให้สำเร็จเพื่อรับ Lumamber และเปิดเผยเรื่องราวที่ซ่อนอยู่เกี่ยวกับอีฟ",
  str_guide_warn_80010104 = "Metamorpha และ Sediment Shards ที่ได้รับในฝันสามารถนำมาแลกของรางวัลต่าง ๆ ที่นี่ รวมถึงชุดของอีฟ",
  str_guide_warn_80010105 = "เครื่องประดับเล็ก ๆ น้อย ๆ ที่รวบรวมไว้ในความฝันนั้นอีฟเก็บไว้อย่างระมัดระวังที่นี่",
  str_guide_warn_80010106 = "ทำภารกิจในฝันให้สำเร็จเพื่อรับชุด Stand By Me",
  str_guide_warn_80010107 = "แตะที่นี่เพื่อดูรายละเอียด",
  str_guide_warn_80010202 = "นี่... ดูเหมือนจะเป็นถ้วยที่คนพิเศษมอบให้ฉัน",
  str_guide_warn_80010203 = "ฉันจำได้ว่าถ้วยใบนี้สามารถมอบพลังพิเศษให้ฉันได้!",
  str_guide_warn_80010204 = "หืม? แก้วว่างเปล่า... ฉันต้องเก็บริมผืนความสุขเพื่อเติมแก้ว! ยิ่งเก็บเยอะยิ่งได้พลังมากขึ้น!",
  str_guide_warn_80010205 = "แต่เดี๋ยวก่อน ... มีคนอยู่ที่ประตูเหรอ?",
  str_guide_circle_80010206 = "ว-นั่นอะไรน่ะ?!",
  str_guide_circle_80010207 = "ไม่มีปัญหา... ฉันไม่กลัว! แตะที่นี่ อยากไปหา!",
  str_guide_warn_80010208 = "ฉันสงสัยว่ามันคือใคร...",
  str_guide_circle_80010304 = "โอ้! เจอแล้ว นั่นมัน...เงาคนเดิมรึเปล่านะ?",
  str_guide_warn_80010305 = "เงานั้นสามารถอัญเชิญ Eclipsites ได้หรือไม่? ตอนนี้ฉันไม่สามารถเพิกเฉยได้ใช่ไหม",
  str_guide_warn_80010306 = "ครูของฉันบอกฉันว่าถ้าศัตรูแข็งแกร่งเกินไป ไม่ต้องยึดติดกับการต่อสู้มากเกินไป คุณสามารถลองเปลี่ยนระดับความยากได้!",
  str_guide_warn_80010307 = "ฝันร้ายท้าทายมากกว่า Reverie แต่ถ้าฉันสามารถผ่านฝันร้ายด้วย 3 ดาว ฉันจะได้รับ Ripples of Joy และสามารถอัพเกรด Smiles Lead to Happiness ได้",
  str_guide_warn_80010308 = "ทุกครั้งที่ฉันเผชิญหน้ากับ Omen Wit ของฉันจะได้รับผลกระทบ...",
  str_guide_warn_80010309 = "แต่ไม่ต้องกังวล! ฉันขยันออกกำลังกายเพื่อให้ร่างกายแข็งแรง ดังนั้นเวลา 05:00 น. ของทุกวัน คะแนนปัญญาจะฟื้นขึ้นมา 3 คะแนน! แต่เมื่อถึงขีดจำกัดสูงสุดแล้ว จะไม่สามารถเพิ่มได้อีก...",
  str_guide_circle_80010402 = "เจอแล้ว!",
  str_guide_warn_80010403 = "อย่างไรก็ตาม ขอพักไว้ก่อน",
  str_guide_warn_80010404 = "หลังจากรวบรวมสิ่งต่างๆ มากมาย จะมีปฏิกิริยาทางเวทมนตร์ระหว่างพวกเขาหรือไม่?",
  str_guide_warn_80010405 = "อ่า... ฉันเกือบลืมไป ฉันยังต้องตามเงานั้นไป!",
  str_guide_warn_80010406 = "เลื่อนหน้าจอเพื่อดูสภาพแวดล้อมโดยรอบ!",
  str_guide_warn_80010407 = "แตะที่นี่เพื่อกลับสู่มุมมองเดิม",
  str_guide_warn_80010408 = "มีอะไรให้ทำมากมาย ดังนั้นจึงควรเก็บข้อมูลไว้ที่นี่ก่อนดีกว่า",
  str_guide_circle_80010501 = "พวกผู้ใหญ่ไม่เคยปล่อยให้ฉันออกไปนอกประตูนี้... ดังนั้นวิธีเดียวคือเปิดมันออกถ้าฉันต้องการออกไป?",
  str_guide_circle_80010502 = "เราจะหา",
  str_guide_circle_80011101 = "ว-ว่าไง?! พวกมันตั้งใจจะทำลายโลกนี้หรือเปล่า... ฮัมฟ์ ไม่ได้หวั่นใจหรอกนะ! แตะที่นี่เถอะ แล้วฉันจะไล่พวกมันด้วยตัวเอง!",
  str_guide_warn_80010601 = "ฉันแข็งแกร่งขึ้น? การต่อสู้ที่กำลังจะเกิดขึ้นควรจะง่ายขึ้นเล็กน้อยในตอนนี้",
  str_guide_warn_80010701 = "ฉันได้รับความสามารถใหม่อย่างสมบูรณ์? ฉันจะลองดูสักหน่อย!",
  str_guide_warn_80010121 = "หืม? อะไรเนี่ย",
  str_guide_warn_80010122 = "ว้าว ดูเหมือนว่าฉันเชี่ยวชาญพลังที่ไม่ธรรมดาเลยนะ? ฮิฮิ ลองใช้มันดูสิ! ดูเหมือนว่ามันสามารถใช้ได้หนึ่งครั้งทุก ๆ รอบเวลา!",
  str_guide_warn_80010521 = "เอ๊ะ พลังของฉันเปลี่ยนไปงั้นเหรอ?",
  str_guide_warn_80010522 = "เลือกพื้นที่? ดูเหมือนจะไม่ยาก ฉันเข้าใจคุณแล้ว!",
  str_guide_warn_80010931 = "เชี่ยวชาญพลังใหม่หรือไม่?",
  str_guide_warn_80010932 = "เอาล่ะ ลงมือทำกันเลย!",
  str_guide_warn_80011331 = "พลังของฉันเปลี่ยนไปอีกแล้ว...",
  str_guide_warn_80011332 = "ดูเหมือนว่าตอนนี้ฉันสามารถปลดปล่อยพลังนี้ได้อย่างไม่มีวันหยุด...",
  str_guide_warn_80011631 = "ฉันเชี่ยวชาญพลังอื่นแล้ว!",
  str_guide_warn_80011632 = "ด้วยพลังนี้ ฉันจะไม่ลังเลอีกต่อไป!",
  str_guide_warn_12300101 = "ดูเหมือนว่าคุณพอใจกับรีสอร์ท ฉันสามารถคุยกับคุณในที่ส่วนตัวได้หรือไม่?",
  str_guide_warn_12300201 = "สถานที่ต่าง ๆ ได้ผลิตเหรียญ Pass Coins ใหม่อีกครั้ง คุณต้องเก็บและใช้พวกเขาเพื่อสร้างวงกลมความดี",
  str_guide_warn_12300202 = "เหรียญ Pass ของเขตโรงแรมพร้อมสำหรับการรวบรวมแล้ว งานของผู้ช่วยคือหาวิธีใช้ประโยชน์จากเหรียญเหล่านี้อย่างมีประสิทธิภาพ",
  str_guide_warn_12300203 = "คุณถามฉันว่า Pass Coins ใช้อย่างไรใช่ไหม? เพียงใช้พวกมันในการอัปเกรดสถานที่ต่างๆ โดยตรงเท่านั้น สถานที่ที่ได้รับการอัปเกรดจะผลิต Pass Coins ให้เร็วขึ้นด้วย นี่คือวิธีที่ธุรกิจใช้เงินในการสร้างเงินมากขึ้น",
  str_guide_warn_12300204 = "คุณอยากรู้ว่าทำไมคุณไม่สามารถรวบรวมเหรียญ Pass ทั้งหมดในครั้งเดียวได้หรือไม่? นี่เป็นเพราะความพิจารณาด้านความปลอดภัย สิ่งสำคัญที่สุดคือการรู้สึกมั่นใจที่สุดในการเก็บเหรียญทีละครั้งและถือไว้!",
  str_guide_warn_12300205 = "คุณยังจำวิธีการอัปเกรดสถานที่ได้หรือไม่? ลองทำดูกันเถอะตอนนี้!",
  str_guide_warn_12300301 = "เพื่ออัปเกรดสถานที่ คุณต้องใช้เหรียญ Pass และต้องตรงตามเงื่อนไขบางประการ ไหนดูซิ... ถูกต้อง! ตัวนี้สามารถอัปเกรดได้ตอนนี้",
  str_guide_warn_12300302 = "สิ่งอำนวยความสะดวกที่ได้รับการอัปเกรดจะเป็นที่นิยมมากขึ้นและสามารถผลิตเหรียญ Pass Coins ได้อย่างมีประสิทธิภาพมากขึ้น การอัปเกรดสิ่งอำนวยความสะดวกยังจะปลดล็อกการผจญภัยกับออโรเรียนคนอื่น ๆ และอัปเกรดรางวัล",
  str_guide_warn_12300303 = "แตะที่นี่เพื่อลงนามในแผนอัปเกรดและเสร็จสิ้นการอัปเกรด",
  str_guide_warn_12300401 = "อัปเกรดเรียบร้อยแล้วนะ! ฉันยังเก็บเหรียญ Pass Coins ที่คุณลืมเก็บก่อนหน้านี้ให้คุณด้วย ขอรับไว้ด้วยความยินดีนะ!",
  str_guide_warn_12300501 = "ฉันคิดว่าคุณปลดล็อคการผจญภัยกับออโรเรียนคนอื่น ๆ แล้ว ไปดูกันเถอะ",
  str_guide_warn_12300601 = "ดูเหมือนว่าจะมีเด็กหญิงที่สวยงาม ฉลาด อ่อนโยน และน่าพอใจกำลังรอคุณอยู่นะ",
  str_guide_warn_12300701 = "เกี่ยวกับวิธีการปลดล็อกการผจญภัยกับออโรเรียน... ฉันคิดว่าฉันไม่จำเป็นต้องสอนคุณเรื่องนี้ใช่มั้ย?",
  str_guide_warn_12300801 = "คุณสามารถดูการผจญภัยที่ปลดล็อคแล้ว และรีวิวการผจญภัยที่คุณเคยประสบใน ผู้นำทางการผจญภัย",
  str_guide_warn_12300802 = "หากคุณมีคำถามเกี่ยวกับการดำเนินงานของรีสอร์ท คุณสามารถดูในคู่มือที่ฉันเตรียมไว้เฉพาะสำหรับคุณ",
  str_guide_warn_12400101 = "กิจกรรมหุบเขาโอเอซิสเริ่มขึ้นแล้ว! ในช่วงกลางวันเราจะสำรวจสิ่งอำนวยความสะดวกต่าง ๆ ภายในดินแดนมหัศจรรย์",
  str_guide_warn_12400102 = "ในช่วงเทศกาลกลางคืน เราจะเผชิญกับความท้าทายที่ยากขึ้นในสวนสนุกภายใต้ความมืดมิด",
  str_guide_warn_12400103 = "ใน Park Tycoon เราจะรับผิดชอบในการจัดการสวนสนุก อย่าลืมดูแลมันให้ดี!",
  str_guide_warn_12400104 = "Claw Machine Token ที่ได้รับจากการทำด่านกิจกรรมและการใช้ Prism สามารถใช้เพื่อแลกรางวัลต่างๆ จาก Claw Machines",
  str_guide_warn_12400105 = "อย่าลืมล็อคอินเข้าเกมทุกวันเพื่อรับรางวัล Guest Sign-in Counter",
  str_guide_warn_12400106 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_12400107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_12500101 = "A Symphony of Gloaming พร้อมให้เล่นแล้ว มาทำภารกิจให้สำเร็จจากเพื่อนอิลลูมินาของคุณในเกม Twilight Tactics และสร้างเมืองขึ้นมาใหม่!",
  str_guide_warn_12500102 = "ในเกมเพลย์ On the Cusp of Gloom เราจะส่งทีมล่วงหน้าไปสืบสวนใกล้กับเขตพลบค่ำเพื่อค้นหาแผนของ Eclipsites!",
  str_guide_warn_12500103 = "อย่าลืมเข้าสู่ระบบเกมทุกวันเพื่อรับรางวัลการลงชื่อเข้าใช้ New Forces",
  str_guide_warn_12500104 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_12500105 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_10181401 = "ความทนทานของประตูฐานที่มั่นจะแสดงอยู่ที่นี่ ยิงจรวดของคุณเมื่อ Corrupted Engine VII เข้าใกล้ประตู",
  str_guide_circle_80010521_Lb = "นี่คือคนที่ถือตุ๊กตา เมื่อพ่ายแพ้จะสร้างความเสียหายให้กับ Eclipsites ทั้งหมดบนสนามและส่งต่อตุ๊กตาแบบสุ่ม เมื่อ Eclipsites อื่นพ่ายแพ้ก่อน ผู้ถือตุ๊กตาจะได้รับโล่นับ",
  str_guide_circle_80010521_LbT = "สาเหตุขี้เล่น",
  str_guide_circle_80010521_Rb = "เปิดเผยมายากลด้วยตุ๊กตา!",
  str_guide_circle_80010521_RbT = "ตุ๊กตาขาดๆ",
  str_guide_circle_80010621_Lt = "ในช่วงเริ่มต้นของการต่อสู้ Forest Evil Eyes จะเข้าสู่โหมดสลีปเป็นเวลา 3 รอบ และ Evil Eyes อื่นๆ จะต้องเผชิญกับค่า DEF ที่ลดลงอย่างมากในช่วงเวลานี้ เมื่อถูกโจมตี Evil Eye จะตื่นขึ้น",
  str_guide_circle_80010621_LtT = "ขยัน",
  str_guide_circle_80010621_Lb = "ก่อนจากกัน ขอพักสักนิด...",
  str_guide_circle_80010621_LbT = "ตุ๊กตาขาดๆ",
  str_guide_circle_80010721_Lt = "หากเกราะป้องกันไม่ถูกทำลายหมดเมื่อสิ้นสุดรอบ ศัตรูนี้จะสร้างความเสียหายคงที่ให้กับผู้เล่นครั้งเดียว",
  str_guide_circle_80010721_LtT = "หลงตัวเองโกรธ",
  str_guide_circle_80010721_Rt = "นี่คือ... วิธีเดียวที่จะทำให้คุณสนใจ?",
  str_guide_circle_80010721_RtT = "ตุ๊กตาขาดๆ",
  str_guide_circle_80010821_Lt = "บอสสะสมพลังงานทุก 3 รอบ แต่ละสแต็กของพลังงานให้โบนัส ATK 3% หากสแต็กทั้งหมดไม่ถูกนำออกเมื่อสิ้นสุดรอบ บอสจะได้รับ 8 สแต็กของโล่นับ",
  str_guide_circle_80010821_LtT = "จับเหล็ก",
  str_guide_circle_80010821_Rt = "ทะลุ...กรงขัง...เพียงเพื่อ...ปลุกเธอ...",
  str_guide_circle_80010821_RtT = "ตุ๊กตาขาดๆ",
  str_guide_circle_80010821_Rb = "แต่ละครั้งที่บอสถูกโจมตี เครื่องหมาย 1 กองจะถูกลบออก เครื่องหมายพลังงานเหล่านี้ช่วยเพิ่ม ATK และความอยู่รอดของบอสได้อย่างมาก ดังนั้นการจัดการกับพวกมันโดยเร็วที่สุดจึงเป็นสิ่งสำคัญ!",
