  str_guide_circle_N34_18_1_Rt = "ทุกที่ที่เสนารักษ์อิลลูมินายืนอยู่ ศักดิ์ศรีของพวกเขาเพิ่มขึ้น เพราะพวกเขารู้ว่าบาดแผลของพวกเขาจะไม่ถูกปล่อยไว้ สหพันธ์อิลลูมินาที่รู้จักความจริงนี้ จึงให้การป้องกันที่เพิ่มขึ้นให้กับเสนารักษ์เหล่านี้ ทำให้ความสามารถในการรอดชีวิตของพวกเขาเพิ่มขึ้นอย่างมาก",
