  str_guide_circle_29057011_Rb = "สามารถทำความสะอาดด้วยสกิลความเสียหายพื้นที่ของออโรเรียน",
  str_guide_warn_815000101 = "ทำไมฉันยังหลุดไม่พ้นจากฝันนี้เสียหาย? หรือเพราะพาโลม่า... เธอยังติดอยู่ในฝันอยู่รึเปล่า?\nแตะปุ่มสลับเพื่อเปลี่ยนเป็นโหมดเริ่มต้น ผู้นำทาง คุณช่วยพาโลม่าได้เหมือนวิธีที่คุณช่วยฉันไหม?",
  str_guide_warn_815000102 = "แตะปุ่มสลับอีกครั้งเพื่อเปลี่ยนกลับไปยังโหมดเปิดเผย ผู้นำทาง ดูเหมือนเราสามารถกลับไปในฝันของฉันได้ตามที่เราต้องการ!",
  str_guide_circle_80020201 = "แตะที่ตราชั่งตรงนี้เพื่อช่วยฉันสะท้อนความคิดและการสืบเสาะหาที่ลึกซึ้งยิ่งขึ้น หลังจากที่ฉันสามารถสืบเสาะหาเสร็จสิ้นแล้ว ฉันจึงสามารถดำเนินการกับงานที่ได้รับมอบหมายจากหัวหน้าผู้พิพากษาต่อไป",
  str_guide_circle_80020202 = "อย่างไรก็ตาม ก่อนที่จะเริ่มการสืบเสาะ ฉันต้องรวบรวมหลักฐานและคำให้การเพียงพอ... สังเกตอย่างใกล้ชิด คำใบ้ที่สำคัญต้องอยู่ใกล้ๆ ที่นี่!",
  ["str_guide_circle_CN5-15_Lt"] = "สืบทอดคำสอนจากพ่ออย่างจริงจังและตอบสนองความคาดหวังทั้งหมดของเขา เธอกลายเป็นอิริดอนที่สมบูรณ์แบบที่สุด ผู้พิพากษาสูงสุดที่ยิ่งใหญ่ที่สุดที่เคยรู้จัก!",
  ["str_guide_circle_CN5-15_LtT"] = "อิริดอน: เอกซิมิอุส",
  ["str_guide_circle_CN5-15_Rt"] = "ก่อนทุกครั้งที่ Chain Combo จะสร้างโล่แห่งแสง ป้องกันความเสียหายเท่ากับเปอร์เซ็นต์ของ Max HP",
  ["str_guide_circle_CN5-15_RtT"] = "โล่แห่งแสงสว่าง",
  ["str_guide_circle_CN5-15_Lb"] = "การควบคุมและหลอกลวงคนอื่นด้วยโคลนของเธอ - กลุ่มเหล่านี้ไม่ถือว่าเป็นความผิดในสายตาของเธอเลย; เพราะว่าเธอถืออำนาจสูงสุดในฐานะผู้พิพากษาสูงสุดที่ยิ่งใหญ่ที่สุด",
  ["str_guide_circle_CN5-15_LbT"] = "อิริดอน: โคลนเอกซิมิอุส",
  ["str_guide_circle_CN5-15_Rb"] = "ความเสียหายที่สร้างให้กับอิริดอน: โคลน Eximius จะถูกถ่ายโอนไปยังอิริดอน: Eximius ทันที",
  ["str_guide_circle_CN5-15_RbT"] = "การส่งความเสียหาย",
  ["str_guide_circle_CN5-18_Lb"] = "อยู่นอกสนาม, ต้านดาเมจจากการโจมตีปกติ, สามารถถูกโจมตีได้เฉพาะสกิลเป้าหมายเดียว",
  ["str_guide_circle_CN5-18_LbT"] = "อิริดอน: โคลนเอกซิมิอุส",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "รูปปั้นชนชั้นสูงที่หยิ่งยโส มันสร้าง 1 สแต็กของ Prejudice ให้กับพันธมิตรและพังทลายเมื่อถูกสัมผัส แปลงไทล์ที่พวกเขาอยู่เป็นไทล์สี พร้อมกับลบ 1 สแต็กของ Prejudice",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "รูปปั้นลูกขุน",
  ["str_guide_circle_CN5-4_Rb"] = "ศัตรูเฉพาะมีผลกระทบของโล่แห่งแสง ก่อน Chain Combo แต่ละครั้ง พวกเขาจะสร้างโล่แห่งแสง ป้องกันความเสียหายเท่ากับเปอร์เซ็นต์ของ Max HP ของตัวเอง",
  ["str_guide_circle_CN5-4_RbT"] = "โล่แห่งแสงสว่าง",
  ["str_guide_circle_CN5-8_Lt"] = "ความหยิ่ง, อคติ, และความคิดเสื่อมทราม... ได้รวมตัวกันเป็นปีศาจชั่วร้ายที่เร่ร่อนในลูโมโพลิส ซึ่งสามารถเข้าไปในทุกช่องที่ของเมืองนี้ที่ไม่มีวันสิ้นสุด",
  ["str_guide_circle_CN5-8_LtT"] = "ภูตสีแดงฉาน",
  ["str_guide_circle_CN5-8_Lb"] = "มันสามารถเทเลพอร์ตไปยังตำแหน่งของผู้เล่นที่ใกล้ที่สุด โดยสร้างการโจมตีหลายครั้งและผลักผู้เล่นถอยหลัง ยิ่งมันเทเลพอร์ตไกลเท่าใด การโจมตีของมันก็จะน้อยลง",
  ["str_guide_circle_CN5-8_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_CN5-8_Rb"] = "คริมสันสเปกเตอร์สามารถรบกวนตำแหน่งของผู้เล่น ดังนั้นควรจะกำจัดมันอย่างรวดเร็วหรือย้ายตัวห่างจากมัน",
  ["str_guide_circle_CN5-8_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_n35-7_LtT"] = "สัตว์น้ำแข็ง",
  ["str_guide_circle_n35-7_Lt"] = "ด้วยขนและกรงเล็บคม อิคลิพไซท์ชนิดนี้มีลักษณะคล้ายสัตว์ร้าย ทำให้เหมาะสำหรับการสอดแนมเข้าไปในพื้นที่ชายแดนต่าง ๆ เพื่อติดตาม สำรวจ และล่าสัตว์",
  ["str_guide_circle_n35-7_Lb"] = "มันเลือกสกิลต่าง ๆ ขึ้นอยู่กับตำแหน่งของ Aurorian และหากการโจมตีของมันไม่สามารถสัมผัส Aurorians ได้ มันจะเลือกที่จะฟื้นฟู HP ของตัวเอง",
  ["str_guide_circle_n35-7_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_n35-7_Rb"] = "คอยสังเกตระยะโจมตีของอิคลิพไซท์ และอยู่เตือนตัวเสมอเกี่ยวกับตำแหน่งของพันธมิตรของเรา!",
  ["str_guide_circle_n35-7_RbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_n35-9_LtT"] = "ไม่ 33",
  ["str_guide_circle_n35-9_Lt"] = "ออโรเรียนจากอดีตที่ห่างไกล รับหน้าที่คุ้มครองปราสาทใต้ดินของเหนือ แม่แบบเอคโค่ของเธอมีข้อผิดพลาดเกิดขึ้นเนื่องจากความเสียหายที่เธอได้รับและการเปิดใช้งานที่ไม่เป็นแนวทาง ต้องการให้คุณเรียนรู้ตัวอย่างและข้อกำหนดด้านบนเพื่อแปลข้อความจากภาษาอังกฤษเป็นภาษาไทยให้กระชับ ถูกต้องและเป็นมิตร",
  ["str_guide_circle_n35-9_Lb"] = "สามารถโทรพอร์ตและรบกวนรูปแบบของช่องกระเบื้อง นอกจากนี้ยังสามารถดูดซับพลังงานจากช่องกระเบื้องเพื่อโจมตีออโรเรียน ช่องกระเบื้องที่สามารถดูดซับพลังงานมากขึ้น ความเสียหายจะสูงขึ้น",
  ["str_guide_circle_n35-9_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_n35-9_Rb"] = "ให้ความสนใจกับการกระจายช่องที่สนามรบและระวังเมื่อศัตรูใช้ทักษะ!",
  ["str_guide_circle_n35-9_RbT"] = "กลยุทธ์รับมือ",
  str_guide_circle_n35_trap5352031_RtT = "ระเบิดมรณะ",
  str_guide_circle_n35_trap5352031_Rt = "ระเบิดเมื่อครบเวลาที่กำหนด ทำดาเมจให้กับยูนิตทั้งหมดบนสนามรบ",
  str_guide_circle_n35_trap5352031_RbT = "กลยุทธ์รับมือ",
  str_guide_circle_n35_trap5352031_Rb = "สั่งการให้ Aurorians ของคุณทำลายศัตรูโดยเร็วที่สุด มิฉะนั้นคุณจะได้รับความเสียหายในเวลานานขึ้น",
  str_guide_warn_53540034 = "ตรงนี้จะแสดงนับถอยหลังที่เหลือสำหรับเขตอาณาจักร",
  str_guide_warn_16000101 = "Enigma Sealed in Ice วางจำหน่ายแล้ว! ถึงเวลาพบกับพันธมิตรใหม่และเริ่มการผจญภัยในการสำรวจ Through the Snow!",
  str_guide_warn_16000102 = "ใน Fatal Trek เราจะเผชิญกับความท้าทายที่ซับซ้อนยิ่งขึ้น",
  str_guide_warn_16000103 = "ในกิจกรรม Ancient Yurt เราสามารถแลกเปลี่ยน Ancient Remains เป็น Solamber, Aurorians 5 ดาว และไอเทมล้ำค่าอื่นๆ ได้ สามารถรับซากโบราณได้โดยผ่านด่านกิจกรรมและใช้ปริซึม",
  str_guide_warn_16000104 = "โหมดตู้เสื้อผ้าของ Zarya ใหม่จะพร้อมใช้งาน แตะที่ทางเข้าของโหมดการเล่นใหม่นี้เพื่อสำรวจมัน!",
  str_guide_warn_16000105 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_16000106 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อรายวัน",
  str_guide_warn_16000107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_9700101 = "Wishlist มีอยู่ในการรับสมัครในเวลาจำกัดนี้ แตะเพื่อเปิดอินเทอร์เฟซ Wishlist",
  str_guide_warn_9700106 = "Wishlist มีให้เฉพาะในการสรรหาบุคลากรเท่านั้น",
  str_guide_warn_9700107 = "ในการรับสมัครครั้งนี้ มี Aurorian ที่มีความน่าจะเป็นเพิ่มขึ้นซึ่งได้รับการแก้ไขไว้ที่จุดสูงสุดของสิ่งที่อยากได้ โดยมีโอกาส 50% ใน Aurorian 6 ดาวทั้งหมดที่มี",
  str_guide_warn_9700108 = "เลือก Aurorian 6 ดาวหนึ่งตัวจากแต่ละธาตุจากสี่ธาตุ และแต่ละธาตุจะมีโอกาส 12.5% ที่จะได้รับ Aurorian 6 ดาว",
  ["str_guide_circle_n36-9_LtT"] = "จักรพรรดิแห่งความตาย",
  ["str_guide_circle_n36-9_Lt"] = "พระองค์จักรพรรดิสูงสุดแห่งความวุ่นวาย พ่อของโทรุ ที่เป็นทหารเก่าผู้มีประสบการณ์ในสงครามมากมาย ไม่ว่าเมื่อไหร่และที่ไหนก็เป็นกำลังอันน่ายืนยันอยู่เสมอ",
  ["str_guide_circle_n36-9_Lb"] = "ด้วยพลังที่น่าเกรงขาม เขาใช้ทักษะหลากหลายในการโจมตีผู้เล่นอย่างแม่นยำหรือปล่อยการโจมตีระยะไกล พร้อมกับผลักคู่ต่อสู้ถอยหลัง",
  ["str_guide_circle_n36-9_LbT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_n36-9_Rb"] = "จักรพรรดิแห่งความตายสามารถถูกส่งผลกระทบโดยสกิลผลักหรือเทเลพอร์ตของผู้เล่น การย้ายตำแหน่งเขาในช่วงเวลาที่เหมาะสมช่วยให้ผู้เล่นหลีกเลี่ยงหรือขัดขวางสกิลโจมตีของเขาได้",
  ["str_guide_circle_n36-9_RbT"] = "กลยุทธ์รับมือ",
  str_guide_warn_17000101 = "วันหยุดของเมดมังกรวางจำหน่ายแล้ว! ได้เวลาพบเพื่อนใหม่และเริ่มผจญภัยใหม่ใน The Road Home!",
  str_guide_warn_17000102 = "ใช้ปริซึมในด่านเนื้อเรื่องหลักและด่านชิงทรัพยากรเพื่อรับจานอาหาร",
  str_guide_warn_17000103 = "ใช้จานอาหารเพื่อรับรางวัลหลากหลายในโทรุคิทเช่น",
  str_guide_warn_17000104 = "ในช่วงอีเวนต์ เข้าร่วมงานชาเคเลสไทต์เพื่อทำควิซสร้างความสัมพันธ์กับออโรเรียน!",
  str_guide_warn_17000105 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ",
  str_guide_warn_17000106 = "เข้าต่อสู้ในการท้าทายของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์พิเศษให้เสร็จสิ้น!",
  str_guide_warn_17000107 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_warn_18000101 = "\"Venom Flows Through Corrupted Hearts\" วางจำหน่ายแล้ว! ได้เวลาพบเพื่อนใหม่และเริ่มผจญภัยใหม่ในคลินิกใต้ดิน!",
  str_guide_warn_18000102 = "ใน \"อดีตที่หม่นหมอง\" เราจะเผชิญกับความท้าทายที่ซับซ้อนยิ่งขึ้น",
  str_guide_warn_18000103 = "เคลียร์ด่านต่าง ๆ ในอีเวนต์และใช้ปริซึม จะได้รับ \"ขวดสะสม\" ที่ใช้แลกของรางวัลต่าง ๆ ได้จาก \"ห้องลับ\"",
  str_guide_warn_18000104 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_warn_18000105 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อรายวัน",
  str_guide_warn_18000106 = "หากมีข้อสงสัยใด ๆ เกี่ยวกับอีเวนต์ สามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  ["str_guide_circle_CN7-15_Lt"] = "จากโลกผิวน้ำไปยังเมืองใต้น้ำ มีผู้มีอิทธิพลและโหดร้ายชนชั้นสูง",
  ["str_guide_circle_CN7-15_LtT"] = "ราชามนุษย์เงือก",
  ["str_guide_circle_CN7-15_Rt"] = "การโจมตีทำให้เกิดผลกระเด็น สามารถเรียกปืนยิงกระสุนต่อเนื่องที่ขอบสนามรบได้",
  ["str_guide_circle_CN7-15_RtT"] = "ลักษณะของศัตรู",
  ["str_guide_circle_CN7-15_Lb"] = "ให้ความสนใจกับระยะโจมตีของปืนยิงคู่ที่อยู่รอบ ๆ สนามรบ กำจัดปืนใหญ่ในเวลาที่เหมาะสมเพื่อยุติการต่อสู้อย่างรวดเร็ว",
  ["str_guide_circle_CN7-15_LbT"] = "กลยุทธ์รับมือ",
  ["str_guide_circle_CN7-5_Lt"] = "อิคลิพไซท์ที่คล้ายกับลำกล้องปืน ให้การสนับสนุนแก่เพื่อนร่วมทีมและโจมตีทีมของคุณอย่างรุนแรง!",
  ["str_guide_circle_CN7-5_LtT"] = "ปืนซัลโว",
  ["str_guide_circle_CN7-5_Rt"] = "ยิงศัตรูที่อยู่ในระยะโจมตี หากไม่มีเป้าหมาย การโจมตีจะเพิ่มพลังและรักษาเจ้าพ่อเงือก",
  ["str_guide_circle_CN7-5_RtT"] = "ปืนหนัก",
  ["str_guide_circle_CN7-7_Lt"] = "พันธมิตรไม่สามารถเชื่อมต่อผ่านทางนี้ได้ เช่นเดียวกับยูนิตศัตรูลงพื้น แต่สิ่งนี้จะไม่ส่งผลกระทบต่อผลของสกิลใด ๆ ที่ถูกสาป",
  ["str_guide_circle_CN7-7_LtT"] = "กำแพงต้องห้าม",
  str_guide_circle_80030101 = "ด้วยกล้องส่องทางไกล คุณสามารถมองเห็นปราสาทใหญ่ในที่ไกล - วัดของพระเจ้าแห่งน้ำ",
  str_guide_warn_80030102 = "แตะปุ่มก่อตั้งวัดและคอนนอลลีจะเดินทางไปยังสถานที่ที่มีมุมมองที่สมบูรณ์แบบของวัด พร้อมกับหนวดยักษ์ที่เชื่องช้า ในการดำเนินโครงการฟื้นฟูวัดต่อไป",
  str_guide_warn_80030301 = "นาวิเกเตอร์ยินดีต้อนรับสู่พิธีผสม! วางเศษอควาในพื้นที่ผสมที่ศูนย์กลางของพิธีผสมเพื่อช่วยฉันในการทำพิธี ซึ่งจะช่วยเสริมความแข็งแกร่งให้แอนตัน!",
  str_guide_warn_80030302 = "เศษอควาชาร์ดประกอบด้วยพลังของ Anton แต่ละชิ้นมีพลังฟิวชั่นที่แตกต่างกัน ภายใต้เงื่อนไขเฉพาะบางอย่าง อาจมีเศษคริสตัลที่ปล่อยพลังเสริมเพิ่มเติม",
  str_guide_warn_80030303 = "ลากเศษคริสตัลน้ำไปยังตำแหน่งที่เหมาะสมในพื้นที่ผสมผสาน หลังจากวางสำเร็จ พิธีการผสมผสานจะนำทางและสกัดพลังการผสมผสานที่อยู่ภายใน",
  str_guide_warn_80030304 = "หลังจากวางเศษคริสตัลน้ำสำเร็จแล้ว คุณสามารถแตะเพื่อเลือกและย้ายหรือปรับตำแหน่ง ลองสำรวจการวางตำแหน่งที่แตกต่างกันเพื่อดึงความสามารถในการรวมตัวมากขึ้น",
  str_guide_warn_80030305 = "ขณะเลือก แตะปุ่มหมุนเพื่อหมุนชิ้นส่วนตามเข็มนาฬิกา 90 องศา",
  str_guide_warn_80030306 = "ขณะที่เลือกอยู่ ให้แตะปุ่มยกเลิกเพื่อนำชิ้นส่วนกลับมา",
  str_guide_warn_80030307 = "ที่นี่คุณจะพบพลังงานรวมที่ได้จากการรวมของ Aqua Shards ที่วางอยู่ในปัจจุบันและพลังงานที่จำเป็นในการสมบูรณ์พิธี Fusion Ritual นี้!",
  str_guide_warn_80030308 = "แตะปุ่มเคลียร์เพื่อลบชิ้นส่วนอควาชาร์ดที่วางทั้งหมด กรุณาใช้ความระมัดระวัง!",
  str_guide_warn_80030309 = "เมื่อพลังงานรวมตรงตามความต้องการสำหรับพิธีการผสาน ให้แตะปุ่มเสร็จสิ้นเพื่อทำให้พิธีการเสร็จสมบูรณ์และคืนความแข็งแกร่งให้แอนตัน!",
  str_guide_warn_18100101 = "ช่วยดูให้หน่อยสิครับ! มันเกิดอะไรขึ้นที่นี่เนี่ย!",
  str_guide_warn_18100102 = "นี่คือที่ที่คุณสามารถเริ่มการฝึกฝน! เล่นด่านการฝึกฝนเพื่อรับคะแนนและรางวัลด่าน!",
  str_guide_warn_18100103 = "โปรดทราบ: ในโมดูลการฝึกฝน มีความสัมพันธ์ระหว่างออโรเรียนบางคน หากออโรเรียนที่มีความสัมพันธ์ถูกส่งออกพร้อมกัน พวกเขาจะได้รับโอกาสมากขึ้นในการเข้าร่วมการต่อสู้",
  str_guide_warn_18100104 = "เมื่อมีออโรเรียนของฝ่ายที่กำหนดอย่างน้อย 3 คนถูกวาง, การเอาช่องหลายๆ ช่องออกในระหว่างการฝึกสามารถเปิดใช้งานสกิลสนับสนุนฝ่าย",
  str_guide_warn_18100105 = "การทำฝึกฝนให้เสร็จสิ้นจะทำให้คุณได้คะแนน และเมื่อคุณสะสมคะแนนในแต่ละเซสชันถึงจำนวนที่กำหนด คุณจะได้รับรางวัลพิเศษ",
  str_guide_warn_18100106 = "การทำด่านฝึกฝนให้เสร็จสิ้นจะทำให้คุณได้รับรางวัล จำนวนสูงสุดของรางวัลที่คุณสามารถได้รับในแต่ละเซสชันจะแสดงที่นี่",
  str_guide_warn_18100107 = "หากคุณมีคำถามใด ๆ สามารถดูคำอธิบายละเอียดได้ที่นี่",
  str_guide_warn_18100108 = "จำนวนรอบทั้งหมดในแต่ละวงรอบการฝึกฝนถูกจำกัด และ HP รวมของทีมจากด่านหนึ่งไปยังอีกด่านหนึ่งจะถือค่าต่อไป",
