  str_guide_warn_19000105 = "เมื่อจำนวนเรลิกที่เหมือนกันในพื้นที่กู้คืนถึง 3 ชิ้น เรลิกจะถูกกู้คืนสำเร็จและนำออกจากช่องสล็อต",
  str_guide_warn_19000106 = "ที่นี่ให้ใช้ฟังก์ชันเก็บเรลิกเพื่อย้ายเรลิกจากช่องกู้คืนไปยังสนาม ป้องกันความล้มเหลวเนื่องจากช่องเต็มทั้งหมด",
  str_guide_cage_Rt = "สามารถทำลายได้ด้วยสกิลดาเมจพื้นที่ของออโรเรียน ศัตรูใหม่อาจปรากฏหลังจากที่ถูกทำลาย!",
  str_guide_cage_RtT = "กับดักพิเศษ - กรง",
  str_guide_circle_N38boss_Lt = "อาวุธอันตรายที่สร้างขึ้นจากการผสมความน่ากลัวของหลายสิ่งประดิษฐ์เชิงกล รวมถึงเทคโนโลยีจากอัสตรา แหล่งพลังงานธรรมดาไม่สามารถทำให้สิ่งมีชีวิตยักษ์ตัวนี้ทำงานต่อไปได้",
