  str_guide_circle_N38boss_Rt = "แต่ละสัตว์เครื่องปั่นที่เป็นส่วนหนึ่งของร่างกายมีการโจมตีที่ไม่ซ้ำกัน หางสามารถสะสมพลังงานเพื่อสร้างความเสียหายแน่นอนให้กับเป้าหมาย แต่ก็อ่อนแอเมื่อเทียบกับส่วนอื่น ๆ",
  str_guide_circle_N38boss_RtT = "ลักษณะของศัตรู",
  str_guide_circle_N38boss_Lb = "โจมตีหางของมันด้วยออโรเรียนสไนเปอร์ก่อนเพื่อทำให้มันไม่สามารถเคลื่อนไหวชั่วคราว จากนั้นใช้โอกาสนี้สร้างความเสียหายให้มากที่สุด",
