  str_guide_crab_Rt = "สร้างเครื่องมือกลไกนี้ขึ้นมาเพื่อช่วยช่างฝีมือสร้างสิ่งประดิษฐ์ที่ประดิษฐ์นัก ในภายหลัง มันถูกปรับเปลี่ยนให้สามารถเก็บแรงงานแสงไฟในท้องของมัน มันไม่เคยถูกตั้งใจให้ใช้เป็นอาวุธ",
