  str_guide_circle_laolong_Rt = "แตะที่กับดักและใช้ 3 แต้มพลังเพื่อปล่อยศัตรูออกจากกรง แม้ว่าพวกเขาจะไม่ช่วยคุณในการต่อสู้ แต่ความเสียหายที่พวกเขาได้รับจะถูกโอนไปยังเจ้าของร้านบางส่วน",
  str_guide_circle_paotai_LtT = "ป้อมปืนคล่องแคล่ว",
  str_guide_circle_paotai_Lt = "ป้อมปืนสูงสมรรถนะ แม้ว่าจะต้องการการดำเนินการด้วยมือ แต่มีโอกาสที่จะมีประสิทธิภาพมากกว่าป้อมปืนอัตโนมัติ",
  str_guide_circle_paotai_RtT = "ลักษณะของกับดัก",
  str_guide_circle_paotai_Rt = "แตะที่กับดักและใช้จุดพลัง 2 จุดเพื่อเริ่มการโจมตี 1 ครั้ง สร้างความเสียหายและ debuffs ให้กับศัตรูที่อยู่ในเส้นตรงข้างหน้า",
  str_guide_circle_fengchuan_RtT = "ลักษณะของกับดัก",
  str_guide_circle_fengchuan_Rt = "กลายเป็นอุปกรณ์ที่พกพาและใช้งานได้ง่ายยิ่งขึ้น สามารถปล่อยทักษะโดยใช้คะแนนพลังของทีม",
  str_guide_circle_8024001 = "ในการขจัดความชั่วร้ายในความเงียบของคืน, ทีมจะไม่ย้ายตามกฎเดิม แต่จะใช้ Force Points สำหรับการเคลื่อนที่",
  str_guide_circle_8024002 = "คะแนน Force ปัจจุบันของผู้เล่นจะแสดงอยู่ทางด้านซ้าย ที่สามารถดูตัวอย่างแบบเรียลไทม์ของคะแนน Force ที่เหลืออยู่ระหว่างการเชื่อมต่อช่องสี",
  str_guide_circle_8024003 = "การเคลื่อนไหวก่อนหน้านี้ดูเหมือนจะทำให้คุณใช้จุดพลังไปหมดแล้ว แต่ไม่ต้องกังวล; คุณจะได้รับจำนวนหนึ่งของจุดพลังในตอนเริ่มแต่ละรอบ และการเติมเต็มในรอบถัดไปจะแสดงอยู่ทางด้านขวาสุด",
  str_guide_circle_8024004 = "แตะที่นี่เพื่อดูผลของความสามารถที่กำลังใช้งานอยู่",
  str_guide_circle_8024005 = "คะแนน Force ที่ไม่ได้ใช้ในแต่ละรอบจะไม่หายไปในท้ายรอบ บางครั้งการเก็บคะแนน Force ของรอบนั้น ๆ อาจเป็นการตัดสินใจที่ฉลาด",
  str_guide_season_talent_tree_1 = "การเลือก Knack ประกอบด้วยหลายๆ โหนดการจัดรูปแบบและ Knacks และให้โบนัสเพิ่มเติม มาเริ่มต้นด้วยการเปิดใช้งานโหนดการจัดรูปแบบครั้งแรกกันเถอะ!",
  str_guide_season_talent_tree_2 = "แตะที่ \"เปิดใช้งาน\" เพื่อใช้พลังงานมงคลเพื่อเปิดใช้งานโหนดขบวนทัพครั้งแรก",
  str_guide_season_talent_tree_3 = "เมื่อโหนดรูปแบบถูกเปิดใช้งาน ผลของมันจะเริ่มมีผลในการต่อสู้ นอกจากนี้ยังสามารถปลดล็อคช่อง Knack ในบางโหนดรูปแบบได้",
  str_guide_season_talent_tree_4 = "ตอนนี้ลองทำการเปิดใช้งานและติดตัวสกิลติดตัวครั้งแรกดูสิ กรุณาแตะสกิลติดตัวนี้",
  str_guide_season_talent_tree_5 = "แตะที่ \"เปิดใช้งาน\" เพื่อใช้พลังงานมงคลและเปิดใช้งาน Knack นี้",
  str_guide_season_talent_tree_6 = "หลังจากเปิดใช้งาน Knack ให้ลากไปยังช่อง Knack ที่สอดคล้องเพื่อสวมใส่และใช้ผลของมันในการต่อสู้",
  str_guide_season_talent_tree_7 = "ช่องสกิลมีข้อจำกัดเฉพาะประเภทสกิล ช่องสกิลแรกสามารถติดตั้งสกิล Caelestite เท่านั้น และช่องอื่น ๆ สามารถติดตั้งสกิล Passive เท่านั้น",
  str_guide_season_talent_tree_8 = "โปรดดูข้อมูลการเล่นเพื่อรายละเอียดเกี่ยวกับกติกาเพิ่มเติม",
  str_guide_season_trade_out_1 = "\"พ่อค้ากลางวัน\" เป็นการเล่นใหม่ที่ผู้นำทางสามารถจัดการท่าเรือและเรือเพื่อสร้างรายได้จากการทำงานและพลังงานมงคล",
  str_guide_season_trade_out_2 = "การขจัดความชั่วร้ายในคืนที่เงียบสงบเป็นการเล่นใหม่ที่มีด่านแบบเชื่อมต่อกัน ในการเล่นนี้ ผู้นำทางจะเคลื่อนที่ตามระบบใหม่และใช้ความชำนาญในฟงชุยเพื่อเพิ่มเปรียบในการต่อสู้!",
  str_guide_season_trade_in_1 = "ผู้นำทางจะต้องจัดการท่าเรือและเรือ และสามารถแตะที่ \"การปรับปรุงอัปเกรด\" ที่มุมบนขวาเพื่ออัปเกรดเป้าหมายที่เลือก",
  str_guide_season_trade_in_2 = "ระดับท่าเรือและเรือจะมีผลต่อความเร็วในการถ่ายโอนสินค้าที่ท่าเรือ น้ำหนักที่เรือยังสามารถบรรทุกได้ และเวลาที่จำเป็นในการถ่ายโอนสินค้าหลังจากการเดินทางเสร็จสิ้น",
  str_guide_season_trade_in_3 = "ลูกเรือที่ได้รับจ้างสามารถถูกมอบหมายให้กับเรือที่หลากหลาย แต่ลูกเรือแต่ละคนสามารถถูกมอบหมายให้กับเรือเพียงลำเดียวในแต่ละครั้งเท่านั้น",
  str_guide_season_trade_in_4 = "สมาชิกลูกเรือมีคุณสมบัติในการส่งมอบ ความสามารถในการขนส่ง และความพร้อม อัปเกรดท่าเรือเพื่อจ้างสมาชิกลูกเรือที่มีความสามารถมากขึ้น",
  str_guide_season_trade_in_5 = "สถานะเรือของแต่ละลำจะถูกกำหนดโดยคะแนนความสามารถของสมาชิกลูกเรือที่ได้รับมอบหมายให้ดูแลเรือ หากเรือไม่ได้รับความต้องการระดับเรือ สถานะเรือของมันจะต่ำอย่างมาก ซึ่งจะส่งผลกระทบต่อกำไรของมัน",
  str_guide_season_trade_in_6 = "พบกับเป้าหมายของเวทีทุนหมุนเวียนต่าง ๆ ในการเดินทางเพื่ออัปเกรดระดับความเจริญรุ่งเรืองของกิลด์และรับรางวัลเพิ่มเติม!",
  str_guide_season_trade_in_7 = "พยายามอย่างหนักในการอัปเกรดท่าเรือและเรือ มอบหมายลูกเรือที่เหมาะสมให้กับเรือ และตอบสนองต่อเหตุการณ์การเดินเรืออย่างเหมาะสมเพื่อทำกำไรมากขึ้นจากการเดินทางทางทะเล!",
  str_guide_season_trade_in_8 = "โปรดดูข้อมูลการเล่นเพื่อรายละเอียดเพิ่มเติมเกี่ยวกับกติกา",
  str_guide_mouse_Rt = "อสูรขนาดเล็กที่กินทั้งพืชและเนื้อสัตว์ มีการปลูกฝังที่ไม่เพียงพอ ยังคงความเถื่อน พวกมันมักจะเล่นงานเข้าไปในที่อยู่ของออโรเรียนเพื่อขโมยอาหาร บางตัวที่รุนแรงอาจจะทำให้เกิดความเสียหาย.",
  str_guide_mouse_RtT = "ใจร้าย: หนู",
  str_guide_mouse_Lt = "ว่องไวและรวดเร็ว มันเคลื่อนไหวอย่างรวดเร็วไปข้างหลังเป้าหมายหลังจากโจมตี",
  str_guide_mouse_LtT = "ลักษณะของศัตรู",
  str_guide_mouse_Lb = "เล็งโจมตีออโรเรียนที่มี DEF ต่ำที่สุดในทีมเมื่อโจมตี ทำให้เกิดความเสียหาย พยายามหลีกเลี่ยงการส่งออโรเรียนที่มี DEF ต่ำเข้าสู่การต่อสู้",
  str_guide_mouse_LbT = "กลยุทธ์รับมือ",
  str_guide_circle_2909301_Lt = "ตำนานกล่าวไว้ว่าในวันก่อนเทศกาลฤดูใบไม้ผลิ สัตว์ร้ายที่เหมือนอสูรจะลงมาที่หลงโจว ทำให้เกิดความวุ่นวาย ผู้ที่สามารถขับไล่มันได้จะได้รับความสงบสุขและโชคดีตลอดทั้งปี",
  str_guide_circle_2909301_LtT = "Fiendling: Nian",
  str_guide_circle_2909301_Rt = "ใช้สกิลใช้งานเพื่อทำให้นิเอนตกใจ ทำให้การเคลื่อนที่ของมันช้าลง",
  str_guide_circle_2909301_RtT = "กลยุทธ์รับมือ",
  str_guide_circle_2909301_Lb = "กระโดดไปข้างหน้าและทำความเสียหาย ทำให้ 1 กลุ่มรอบ ๆ ไม่สามารถผ่านไปได้ หาก Nian ทำลายประตู การต่อสู้จะสิ้นสุดลงด้วยความพ่ายแพ้",
  str_guide_circle_2909301_LbT = "ลักษณะของศัตรู",
  str_guide_circle_80050001_Rt = "ได้รับ 10 แต้มพลังงานการต่อสู้ในแต่ละรอบ ให้ ATK สูงขึ้นสำหรับมอนสเตอร์ทั้งหมดในสนาม ถ้ามีพลังงานมากกว่า 30 แต้มในท้ายรอบ",
  str_guide_circle_80050001_RtT = "อินเทลอิคลิพไซท์ - คูเรียร์",
  str_guide_circle_80050001_Rb = "เมื่อออโรเรียนทำความเสียหายต่อคูเรียร์ด้วยสกิลใช้งานและการโจมตีปกติ พวกเขาสามารถลดพลังงานการต่อสู้ของมัน คูเรียร์ทำความเสียหายต่อมอนสเตอร์ทั้งหมดในสนามเมื่อถูกกำจัด",
  str_guide_circle_80050001_RbT = "กลยุทธ์รับมือ",
  str_guide_warn_80050111 = "ผู้นำทาง มองมาที่นี่สิ! คุณได้ความสามารถใหม่ในฝันแล้ว!",
  str_guide_warn_80050112 = "ความสามารถของคุณจะแข็งแกร่งขึ้นเมื่อคุณทำการสำรวจในฝันอย่างลึกซึ้ง ใช้มันอย่างดีเถอะ!",
  str_guide_circle_80150101 = "ทีมจะไม่เคลื่อนที่ตามกฎเดิมอีกต่อไป แต่จะใช้ Force Points สำหรับการเคลื่อนที่ โดยไม่คำนึงถึงสีของกระเบื้อง",
  str_guide_circle_80150102 = "ที่นี่แสดงคะแนนพลังของผู้เล่น จัดเรียงจากซ้ายไปขวาเป็น คะแนนพลังปัจจุบัน, การเก็บรักษาสูงสุด, และการฟื้นฟูคะแนนพลัง",
  str_guide_circle_80150103 = "เมื่อเริ่มต้นแต่ละรอบ ผู้เล่นจะฟื้นฟู Force Points โดยอัตโนมัติตามจำนวนที่แสดงใน Force Point Recovery ซึ่งจะเพิ่มขึ้นในแต่ละรอบ",
  str_guide_circle_80150201 = "ในการเล่นนี้ ผู้เล่นจะได้รับ 1 แต้มพลังทุกครั้งที่ใช้กระเบื้องสีดำ",
  str_guide_circle_80150301 = "แตะเพื่อเลือกหินและใช้คะแนนพลังเพื่อเคลียร์มัน",
  str_guide_circle_80250101 = "ในการเล่นนี้ เมื่อผู้เล่นใช้ทักษะคอมโบต่อเนื่อง ช่องที่มืดจะถือว่าเป็น 2 ช่องสำหรับการบริโภค",
  str_guide_circle_2921201_Lt = "หัวหน้าของ Silent Hunters ตอนนี้ได้หันมาใช้ดาบต่อสู้กับเพื่อนร่วมทีมที่เคยไว้วางใจเขา... นี่คือระดับที่เขาได้ทำความประนีประนอมกับราชอาณาจักร",
  str_guide_circle_2921201_LtT = "เคลย์มอร์",
  str_guide_circle_2921201_Rt = "ขึ้นอยู่กับสภาพสนามรบ เคลย์มอร์สามารถเลือกที่จะเคลื่อนที่โดยการเชื่อมต่อช่องแล้วจึงโจมตี หรือเปิดการโจมตีคู่หลังจากการเคลื่อนที่ปกติ เมื่อ HP ลดลง เขาสามารถปล่อยทักษะพิเศษเพื่อแบ่งสนามรบ ต่อสู้กับศัตรูในพื้นที่ที่มีขนาดเล็กลง",
  str_guide_circle_2921201_RtT = "ลักษณะของศัตรู",
  str_guide_circle_2921201_Lb = "ตรวจสอบให้แน่ใจว่าคุณไม่ถูกสกิลพิเศษโจมตี; ส่วนที่เหลือขึ้นอยู่กับความสามารถของคุณ",
  str_guide_circle_2921201_LbT = "กลยุทธ์รับมือ",
  str_guide_circle_2909401_Lt = "เจตภูตที่ลึกลับและน่ากลัว ท่องทุ่งเพื่อการฝึกฝน ลมหายใจของเขาส่งออกความหวาดกลัว คาดการณ์ความพิการสำหรับผู้ที่ทำให้เขาระเบิดวราธ",
  str_guide_circle_2909401_LtT = "ไอรา",
  str_guide_circle_2909401_Rt = "สามารถเรียกแชโดว์ไฟร์ด้วยพลังความมืดในการต่อสู้",
  str_guide_circle_2909401_RtT = "ลักษณะของศัตรู",
  str_guide_circle_2909401_Lb = "หมายเหตุ: อิราส์ดาร์กโฟลว์เมทีโอไรท์ ที่ประกอบด้วยเปลวไฟที่รุนแรง สามารถฆ่า Aurorians ที่อยู่ในระยะทันที โปรดสังเกตบริเวณที่เตือนและหลีกเลี่ยงอย่างรวดเร็ว!",
  str_guide_circle_2909401_LbT = "กลยุทธ์รับมือ",
  str_guide_n43_1 = "แสงแวววาววางจำหน่ายแล้ว!\nเริ่มเรื่องใหม่ในภาคต่อที่สองกันเถอะ!",
  str_guide_n43_2 = "บทเรื่องที่ถูกปลดล็อกในอีเวนต์นี้ รวมถึงบทที่คุณได้สำรวจมาแล้ว จะถูกแสดงที่นี่",
  str_guide_n43_3 = "แตะที่ 'สำรวจเดี๋ยวนี้' เพื่อไปยังแผนที่สำรวจโดยตรง ใช้ปริซึมในด่านเนื้อเรื่องหลักและด่านชิงทรัพยากรเพื่อรับ Caelestite Feathers",
  str_guide_n43_4 = "ใน Aurora Exchange ใช้ขนนก Caelestite เพื่อแลกเปลี่ยนรางวัลต่างๆ",
  str_guide_n43_5 = "เล่นด่านเนื้อเรื่องของอีเวนต์และทำเควสต์ในหนังสืออีเวนต์\nพิเศษให้เสร็จสิ้น!",
  str_guide_n43_6 = "อย่าลืมเข้าเกมทุกวันเพื่อรับรางวัลลงชื่อ Navigation",
