  str_guide_warn_90010702 = "แจ้งเตือน: แตะที่นี่เพื่อเปิดหน้าจอ Dream Orb",
  str_guide_warn_90010703 = "ประกาศ: มีช่องว่างหลายช่องในสปิรัลการรู้ลึก วาง Dream Orb ลงในช่องว่างเพื่อวิเคราะห์และปลดปล่อยพลังของมัน",
  str_guide_warn_90010704 = "ประกาศ: แตะที่ Dream Orb เพื่อดูรายละเอียด",
  str_guide_warn_90010705 = "คำเตือน: แตะปุ่มติดตั้งเพื่อวาง Dream Orb ลงใน Enlightenment Spiral คุณยังสามารถลาก Dream Orb ไปวางในช่องว่างโดยตรงได้",
  str_guide_warn_90010706 = "ความเห็น: พลังงานที่เพียงพอจำเป็นสำหรับการปลดปล่อยพลังของ Dream Orbs บน Enlightenment Spiral แต่ไม่ต้องกังวล; ในฐานะผู้กระจ่างให้สว่างของคุณ ฉันเชื่อว่าคุณสามารถสะสมพลังงานเพียงพอในการต่อสู้ได้",
  str_guide_warn_90010707 = "คำเตือน: หากคุณมี Dream Orbs หลายลูก ควรรวมพวกมันเข้าด้วยกันเพื่อรับ Dream Orbs ระดับสูงขึ้น",
  str_guide_warn_90010708 = "สอง Dream Orbs ที่มีระดับเดียวกันสามารถสังเคราะห์เป็น 1 Dream Orb ที่มีระดับสูงขึ้น 1 ระดับ",
  str_guide_warn_90010709 = "แจ้งเตือน: หากคุณมีข้อสงสัยใด ๆ คุณสามารถดูคำอธิบายอย่างละเอียดได้ที่นี่",
  str_guide_circle_2004901_LbT = "ควันหมอก",
  str_guide_circle_2004901_Lb = "สร้างขึ้นจากการสะสมพลังความมืดรวดเร็วรอบ ๆ ศัตรูที่ตายไปแล้ว ระวัง! ความโกรธแค้นและความเคียดแค้นของศัตรูของคุณยังอยู่ภายในมัน",
  str_guide_circle_2004901_RtT = "ลักษณะของศัตรู",
  str_guide_circle_2004901_Rt = "ความเสียหายทั้งหมดที่มันได้รับจะลดลงเหลือ 1 มันไม่สามารถโจมตีได้ แต่จะยังคงเคลื่อนที่เข้าหา Aurorians\nHaze ไม่ถูกนับเป็นเงื่อนไขการรีเฟรชคลื่นและเงื่อนไขชัยชนะของเวที",
  str_guide_circle_2004901_RbT = "กลยุทธ์รับมือ",
  str_guide_circle_2004901_Rb = "Haze จะหายไปทันทีเมื่อถูกกระเด็นกลับ, ถูกดึงมา, หรือถูกบังคับให้เคลื่อนที่ และจะหายไปตามปกติหลังจากจำนวนรอบที่กำหนด",
  str_guide_circle_80060313_LbT = "อาวุธเอลิท: ม่านหมอก",
  str_guide_circle_80060313_Lb = "ศัตรูที่มีคุณสมบัติเอลิทนี้จะสร้าง Haze เมื่อตาย ปริมาณที่สร้างขึ้นขึ้นอยู่กับขนาดของศัตรู\nแตะที่ศัตรูเพื่อดูรายละเอียดเพิ่มเติม",
  str_guide_circle_2909501_LbT = "แครอท: โรคไฟท์",
  str_guide_circle_2909501_Lb = "หลังจากดูดซับความเคียดแค้นจำนวนมากในที่ที่มืดมิดและเน่าเปื่อย แครอทตัวนี้ได้ขยายตัวเป็นสิ่งมีชีวิตที่แปลกประหลาด และแสวงหาการแก้แค้นหลังจากได้รับพลังความมืด",
  str_guide_circle_2909501_RtT = "ลักษณะของศัตรู",
  str_guide_circle_2909501_Rt = "โยนแครอท ทำให้เกิดความเสียหายหลายครั้ง ในขณะที่หมุนด้วยความเร็วสูง จะทำให้เกิดความเสียหายหลายครั้งให้กับศัตรูในพื้นที่ขนาดใหญ่และผลักพวกเขาให้กระเด็นถอยหลัง",
  str_guide_circle_2909501_RbT = "กลยุทธ์รับมือ",
  str_guide_circle_2909501_Rb = "ศัตรูตัวนี้มีขนาดใหญ่มาก ใช้ Detonator Aurorians เพื่อทำลายมัน!",
  str_guide_circle_2909502_LbT = "แครอท: โรคไฟท์",
  str_guide_circle_2909502_Lb = "หลังจากดูดซับความเคียดแค้นจำนวนมากในที่ที่มืดมิดและเน่าเปื่อย แครอทตัวนี้ได้ขยายตัวเป็นสิ่งมีชีวิตที่แปลกประหลาด และแสวงหาการแก้แค้นหลังจากได้รับพลังความมืด",
  str_guide_circle_2909502_RtT = "ลักษณะของศัตรู",
  str_guide_circle_2909502_Rt = "โยนแครอททำดาเมจหลายครั้ง ในขณะที่หมุนด้วยความเร็วสูง จะทำดาเมจหลายครั้งใส่ศัตรูในพื้นที่กว้างและผลักให้กระเด็นถอยหลัง ในสถานการณ์ฉุกเฉิน สามารถย่อตัวและขุดหลุมลงไปใต้ดินแล้วดำเนินการต่อสู้จากที่นั่น",
  str_guide_circle_2909502_RbT = "กลยุทธ์รับมือ",
  str_guide_circle_2909502_Rb = "ศัตรูตัวนี้มีขนาดใหญ่มาก ปรับใช้ Detonator Aurorians เพื่อทำลายมัน!\nหมายเหตุ: ศัตรูตัวนี้จะเปลี่ยนรูปเป็นรูปแบบ 4 กระเบื้องเมื่อมันเป็นอมตะ!",
  str_guide_circle_80060101_RtT = "ฝันเลือดออก",
  str_guide_circle_80060101_Rt = "ลักษณะเฉพาะของฝันปัจจุบันที่เปลี่ยนผลกระทบจากการเลือดออกทั้งหมดเป็นผลกระทบจากการบาดเจ็บ สิ่งใดที่ทำให้เกิดผลกระทบจากการเลือดออกจะทำให้เกิดผลกระทบจากการบาดเจ็บด้วย",
  str_guide_circle_80060101_RbT = "ช่างที่บาดเจ็บ",
  str_guide_circle_80060101_Rb = "ขณะที่ถูกบาดเจ็บ ศัตรูจะได้รับความเสียหายในทุกรอบตาม ATK เฉลี่ยของทีม Aurorian ยิ่ง HP ของทีม Aurorian มีอัตราสูงขึ้น สแต็กที่ถูกบาดเจ็บที่สามารถนำมาใช้จะมากขึ้น และสามารถทำให้เกิดความเสียหายมากขึ้น สแต็กที่ถูกบาดเจ็บสะสมได้สูงสุด 5 ครั้ง และไม่หายไปเมื่อรอบสิ้นสุด",
  str_guide_circle_80060102_LtT = "สถานะผู้บาดเจ็บ",
  str_guide_circle_80060102_Lt = "ศัตรูในระยะต้นจะเริ่มต้นด้วยสแต็กสถานะตาบอด 1 สแต็กเป็นค่าเริ่มต้น และได้รับความเสียหายจากสถานะตาบอดในแต่ละรอบ แตะที่ศัตรูเพื่อดูผลของสถานะตาบอด",
  str_guide_circle_80060201_RtT = "ก้อนหินระเบิด",
  str_guide_circle_80060201_Rt = "กองหินที่ดูเหมือนธรรมดา แต่มีความระเบิดแรง หลังจากที่ถูกทำลาย จะทำดาเมจให้กับศัตรูทั้งหมดที่อยู่ใกล้ และสร้างสแต็ก Wounded 1 สแต็ก",
  str_guide_circle_80060201_LtT = "ระเบิดกระจาย",
  str_guide_circle_80060201_Lt = "บางกองหินมีความทนทานอย่างน่าประหลาดใจและจะระเบิดเฉพาะเมื่อถูกโจมตีหลายครั้ง ซึ่งจะเพิ่มรัศมีการระเบิดของพวกเขา 1 ช่องสำหรับทุก HP ที่พวกเขามี",
  str_guide_circle_80060401_RtT = "หนามทื่อที่ถูกแปลงเปลี่ยน",
  str_guide_circle_80060401_Rt = "สไปค์เพสต์ที่ดูคุ้นเคยแต่ไม่เป็นอันตรายต่อออโรเรียนอีกต่อไป ที่สิ้นสุดของแต่ละรอบ มันทำความเสียหายและสร้าง 1 กองที่บาดเจ็บให้กับศัตรูทั้งหมดที่ตกอยู่ในหนามของมัน",
  str_guide_circle_2909701_LbT = "Magmite ไม่รู้จักพอ",
  str_guide_circle_2909701_Lb = "ประเภทของอิคลิพไซท์ที่ผิดปกติที่ใช้ทั้งลาวาและพลังความมืดในการทำความเสียหาย",
  str_guide_circle_2909701_RtT = "ลักษณะของศัตรู",
