  str_guide_warn_811400108 = "แตะที่กล่องเพื่อเลือกเอฟเฟกต์เสริมพลังที่สัมพันธ์กัน",
  str_guide_warn_811400109 = "แตะเพื่อยืนยันและบันทึกเอฟเฟกต์การเพิ่มประสิทธิภาพที่เลือก",
  str_guide_warn_811400110 = "เคลียร์ด่านเพื่อสำเร็จภารกิจท้าทายและรับรางวัลที่ยอดเยี่ยม",
  str_guide_circle_2909801_LbT = "หัวหอก: Rotbone Stinger",
